export const AGENT_PY = "#!/usr/bin/env python3\n\"\"\"resi-agent: VPNGate -> OpenVPN -> SOCKS5/HTTP proxy, managed by the Cloudflare hub.\n\n只依赖 Python3 标准库 + openvpn + iproute2。必须以 root 运行（SO_BINDTODEVICE / ip rule）。\n\"\"\"\nimport asyncio, base64, csv, hmac, io, ipaddress, json, os, random, re, shutil, socket, struct, subprocess, sys, time\nimport urllib.request\nfrom collections import deque\nfrom urllib.parse import urlsplit\n\nHUB = os.environ[\"HUB_URL\"].rstrip(\"/\")\nTOKEN = os.environ[\"AGENT_TOKEN\"]\nNODE_ID = os.environ.get(\"NODE_ID\") or socket.gethostname()\nWORKDIR = os.environ.get(\"WORKDIR\", \"/opt/resi-agent\")\nALLOW_HOSTING = os.environ.get(\"ALLOW_HOSTING\", \"0\") == \"1\"  # 1 = 不过滤机房 IP\nDEV, TABLE = \"tun_rp\", \"100\"\nVPNGATE_API = \"http://www.vpngate.net/api/iphone/\"\nSO_BINDTODEVICE = getattr(socket, \"SO_BINDTODEVICE\", 25)\nSCAN_INTERVAL = int(os.environ.get(\"SCAN_INTERVAL\", \"960\"))  # 自动抓取 + 择优间隔（秒），默认 16 分钟\n\nS = dict(country=\"US\", port=7920, user=\"\", pw=\"\", nonce=None, ready=False, status=\"starting\",\n         exit_ip=\"\", cc=\"\", isp=\"\", hosting=False, latency=0, pin=\"\", pin_fail=\"\",\n         mode=\"country\", proxy_on=True, max_conns=500, skew=0, hub_rtt=0, exclude=set(), prefer=set(),\n         auto_best=True, cur=None, last_ip=\"\", want_ip=\"\")\nROUTE_NAMES = dict(country=\"指定国家(评分)\", latency=\"延迟优先\", speed=\"速度优先\")\n# 代理服务统计\nPROXY = dict(active=0, total=0, rejected=0, up=0, down=0, since=0, listening=False)\nDIAG = dict(nonce=None, running=False, ts=0)\n# 扫描状态：res = 住宅 IP -> 实测延迟；bad = 已确认的机房 IP（建链时直接跳过）\nSCAN = dict(state=\"idle\", ts=0, nonce=None, res={}, bad=set())\nPENDING = deque(maxlen=200)\nrotate_ev = port_ev = scan_ev = diag_ev = None  # 在 main() 里创建，兼容 Python 3.9\n\n\ndef log(msg):\n    line = f\"{time.strftime('%H:%M:%S')} {msg}\"\n    print(line, flush=True)\n    PENDING.append(line)\n\n\n# ---------------------------------------------------------------- hub\ndef hub_post(path, obj):\n    req = urllib.request.Request(\n        HUB + path, data=json.dumps(obj).encode(),\n        headers={\"Authorization\": \"Bearer \" + TOKEN, \"Content-Type\": \"application/json\",\n                 \"User-Agent\": \"resi-agent/1.0\"})\n    with urllib.request.urlopen(req, timeout=10) as r:\n        return json.loads(r.read())\n\n\ndef apply_policy(r):\n    p = r[\"policy\"]\n    country, port = str(p[\"country\"]).upper(), int(p[\"port\"])\n    S[\"user\"], S[\"pw\"] = p.get(\"proxy_user\", \"\"), p.get(\"proxy_pass\", \"\")\n    if S[\"nonce\"] is None:\n        S[\"nonce\"] = r[\"rotate_nonce\"]\n    elif r[\"rotate_nonce\"] != S[\"nonce\"]:\n        S[\"nonce\"] = r[\"rotate_nonce\"]\n        log(\"收到面板的换 IP 指令\")\n        rotate_ev.set()\n    if S[\"ready\"] and country != S[\"country\"]:\n        log(f\"目标国家变更 {S['country']} -> {country}\")\n        rotate_ev.set()\n    exclude = {str(x).upper() for x in (p.get(\"exclude\") or []) if len(str(x)) == 2 and str(x).isalpha()}\n    if exclude != S[\"exclude\"]:\n        if S[\"ready\"]:\n            log(\"不连接的国家变更: \" + (\",\".join(sorted(exclude)) or \"无\"))\n            if S[\"status\"] == \"up\" and not S[\"pin\"] and S[\"cc\"] in exclude:\n                rotate_ev.set()\n        S[\"exclude\"] = exclude\n    prefer = {str(x).upper() for x in (p.get(\"prefer\") or []) if len(str(x)) == 2 and str(x).isalpha()}\n    if prefer != S[\"prefer\"]:\n        if S[\"ready\"]:\n            log(\"优先国家变更: \" + (\",\".join(sorted(prefer)) or \"无\"))\n            if prefer and S[\"status\"] == \"up\" and not S[\"pin\"] and S[\"cc\"] not in prefer:\n                rotate_ev.set()\n        S[\"prefer\"] = prefer\n    S[\"auto_best\"] = bool(p.get(\"auto_best\", True))\n    pin = r.get(\"pin_ip\") or \"\"\n    if pin != S[\"pin\"] and pin != S[\"pin_fail\"]:\n        S[\"pin\"] = pin\n        log(f\"面板指定固定出口 {pin}\" if pin else \"取消固定，恢复自动选择\")\n        rotate_ev.set()\n    sn = r.get(\"scan_nonce\", 0)\n    if SCAN[\"nonce\"] is None:\n        SCAN[\"nonce\"] = sn\n    elif sn != SCAN[\"nonce\"]:\n        SCAN[\"nonce\"] = sn\n        if SCAN[\"state\"] != \"scanning\":\n            log(\"收到面板的扫描指令\")\n            scan_ev.set()\n    mode = p.get(\"mode\", \"country\")\n    if mode not in (\"country\", \"latency\", \"speed\"):\n        mode = \"country\"\n    if S[\"ready\"] and mode != S[\"mode\"]:\n        log(f\"路由模式变更 {S['mode']} -> {mode}\")\n        rotate_ev.set()\n    S[\"mode\"] = mode\n    on = bool(p.get(\"proxy_enabled\", True))\n    if on != S[\"proxy_on\"]:\n        S[\"proxy_on\"] = on\n        log(\"代理服务已\" + (\"启用\" if on else \"停用（不再接受新连接）\"))\n        port_ev.set()\n    S[\"max_conns\"] = max(1, int(p.get(\"max_conns\", 500)))\n    if \"now\" in r:\n        S[\"skew\"] = int(r[\"now\"]) - int(time.time() * 1000)\n    dn = r.get(\"diag_nonce\", 0)\n    if DIAG[\"nonce\"] is None:\n        DIAG[\"nonce\"] = dn\n    elif dn != DIAG[\"nonce\"]:\n        DIAG[\"nonce\"] = dn\n        if not DIAG[\"running\"]:\n            log(\"收到面板的诊断指令\")\n            diag_ev.set()\n    S[\"country\"] = country\n    if port != S[\"port\"]:\n        S[\"port\"] = port\n        port_ev.set()\n    S[\"ready\"] = True\n\ndef get_public_ip():\n    try:\n        return urllib.request.urlopen(\"https://api.ipify.org\", timeout=8).read().decode().strip()\n    except Exception:\n        return \"\"\n\nasync def heartbeat_loop():\n    loop = asyncio.get_running_loop()\n    while True:\n        lines = [PENDING.popleft() for _ in range(min(20, len(PENDING)))]\n        body = dict(node_id=NODE_ID, status=S[\"status\"], exit_ip=S[\"exit_ip\"], country=S[\"cc\"],\n                    isp=S[\"isp\"], hosting=S[\"hosting\"], latency=S[\"latency\"], port=S[\"port\"], logs=lines,\n                    scan_state=SCAN[\"state\"], scan_at=SCAN[\"ts\"], pin_ip=S[\"pin\"], pin_fail=S[\"pin_fail\"],\n                    proxy=proxy_stats())\n        try:\n            t0 = time.time()\n            r = await loop.run_in_executor(None, hub_post, \"/api/agent/heartbeat\", body)\n            S[\"hub_rtt\"] = int((time.time() - t0) * 1000)\n            apply_policy(r)\n            S[\"pin_fail\"] = \"\"  # 面板已收到\n        except Exception as e:\n            print(f\"heartbeat failed: {e}\", flush=True)\n            for l in reversed(lines):  # 放回去，下次再发\n                PENDING.appendleft(l)\n        await asyncio.sleep(30)\n\n\n# ---------------------------------------------------------------- tunnel-bound sockets / DNS\ndef tun_sock(kind=socket.SOCK_STREAM):\n    s = socket.socket(socket.AF_INET, kind)\n    s.setsockopt(socket.SOL_SOCKET, SO_BINDTODEVICE, DEV.encode())\n    return s\n\n\ndef _skip_name(d, i):\n    while True:\n        n = d[i]\n        if n == 0:\n            return i + 1\n        if n & 0xC0 == 0xC0:\n            return i + 2\n        i += n + 1\n\n\ndef parse_a(d):\n    qd, an = struct.unpack(\"!HH\", d[4:8])\n    i = 12\n    for _ in range(qd):\n        i = _skip_name(d, i) + 4\n    for _ in range(an):\n        i = _skip_name(d, i)\n        t, _c, _ttl, rl = struct.unpack(\"!HHIH\", d[i:i + 10])\n        i += 10\n        if t == 1 and rl == 4:\n            return socket.inet_ntoa(d[i:i + 4])\n        i += rl\n    return None\n\n\ndef tun_resolve(name):\n    \"\"\"通过隧道向 1.1.1.1 / 8.8.8.8 查询 A 记录，避免 DNS 走本机出口泄漏。\"\"\"\n    try:\n        ipaddress.ip_address(name)\n        return name\n    except ValueError:\n        pass\n    labels = name.rstrip(\".\").encode(\"idna\").split(b\".\")\n    q = struct.pack(\"!HHHHHH\", random.randrange(65536), 0x0100, 1, 0, 0, 0)\n    q += b\"\".join(bytes([len(x)]) + x for x in labels) + b\"\\0\" + struct.pack(\"!HH\", 1, 1)\n    for server in (\"1.1.1.1\", \"8.8.8.8\"):\n        s = tun_sock(socket.SOCK_DGRAM)\n        s.settimeout(3)\n        try:\n            s.sendto(q, (server, 53))\n            ip = parse_a(s.recvfrom(1500)[0])\n            if ip:\n                return ip\n        except OSError:\n            pass\n        finally:\n            s.close()\n    raise OSError(\"dns failed: \" + name)\n\n\ndef ident():\n    \"\"\"经隧道查询出口 IP / 国家 / ISP / 是否机房（ip-api.com，仅 HTTP）。\"\"\"\n    s = tun_sock()\n    s.settimeout(8)\n    try:\n        s.connect((tun_resolve(\"ip-api.com\"), 80))\n        s.sendall(b\"GET /json/?fields=status,query,countryCode,isp,hosting HTTP/1.0\\r\\nHost: ip-api.com\\r\\n\\r\\n\")\n        data = b\"\"\n        while True:\n            chunk = s.recv(4096)\n            if not chunk:\n                break\n            data += chunk\n        return json.loads(data.split(b\"\\r\\n\\r\\n\", 1)[1])\n    finally:\n        s.close()\n\n\ndef probe():\n    t = time.time()\n    s = tun_sock()\n    s.settimeout(5)\n    try:\n        s.connect((\"1.1.1.1\", 443))\n        return int((time.time() - t) * 1000)\n    except OSError:\n        return None\n    finally:\n        s.close()\n\n\n# ---------------------------------------------------------------- VPNGate / OpenVPN\ndef fetch_vpngate():\n    req = urllib.request.Request(VPNGATE_API, headers={\"User-Agent\": \"Mozilla/5.0\"})\n    raw = urllib.request.urlopen(req, timeout=30).read().decode(\"utf-8\", \"ignore\")\n    lines = [l for l in raw.splitlines() if l and not l.startswith(\"*\")]\n    lines[0] = lines[0].lstrip(\"#\")\n    out = []\n    for row in csv.DictReader(io.StringIO(\"\\n\".join(lines))):\n        try:\n            text = base64.b64decode(row[\"OpenVPN_ConfigData_Base64\"]).decode(\"utf-8\", \"ignore\")\n            proto = \"udp\" if \"proto udp\" in text else \"tcp\"\n            remote = next(l.split() for l in text.splitlines() if l.startswith(\"remote \"))\n            out.append(dict(ip=row[\"IP\"], cc=row[\"CountryShort\"].upper(), score=int(row[\"Score\"]),\n                            speed=int(row[\"Speed\"]) if str(row.get(\"Speed\", \"\")).isdigit() else 0,\n                            ping=int(row[\"Ping\"]) if row[\"Ping\"].isdigit() else 9999,\n                            uptime=int(row[\"Uptime\"]) if str(row.get(\"Uptime\", \"\")).isdigit() else 0,\n                            sessions=int(row[\"NumVpnSessions\"]) if str(row.get(\"NumVpnSessions\", \"\")).isdigit() else 0,\n                            users=int(row[\"TotalUsers\"]) if str(row.get(\"TotalUsers\", \"\")).isdigit() else 0,\n                            text=text, proto=proto, host=remote[1], port=int(remote[2])))\n        except Exception:\n            continue\n    return out\n\n\nasync def tcp_alive(c):\n    if c[\"proto\"] != \"tcp\":\n        return True\n    try:\n        _, w = await asyncio.wait_for(asyncio.open_connection(c[\"host\"], c[\"port\"]), 4)\n        w.close()\n        return True\n    except Exception:\n        return False\n\n\n\n# ---------------------------------------------------------------- 住宅 IP 扫描\ndef ipapi_batch(ips):\n    \"\"\"ip-api 批量接口：每次最多 100 个，免费额度 15 次/分钟。\"\"\"\n    fields = \"status,query,country,countryCode,regionName,city,isp,org,hosting,proxy,mobile\"\n    body = json.dumps([{\"query\": ip, \"fields\": fields, \"lang\": \"zh-CN\"} for ip in ips]).encode()\n    req = urllib.request.Request(\"http://ip-api.com/batch\", data=body,\n                                 headers={\"Content-Type\": \"application/json\", \"User-Agent\": \"resi-agent/1.1\"})\n    with urllib.request.urlopen(req, timeout=20) as r:\n        return json.loads(r.read())\n\n\nasync def tcp_rtt(host, port, n=3):\n    \"\"\"真实 TCP 握手耗时（取中位数），从本 VPS 的默认出口测量，不经隧道。\"\"\"\n    vals = []\n    for _ in range(n):\n        t = time.perf_counter()\n        try:\n            _, w = await asyncio.wait_for(asyncio.open_connection(host, port), 3)\n            vals.append((time.perf_counter() - t) * 1000)\n            w.close()\n        except Exception:\n            pass\n    return int(sorted(vals)[len(vals) // 2]) if vals else None\n\n\nasync def icmp_rtt(host):\n    try:\n        p = await asyncio.create_subprocess_exec(\"ping\", \"-n\", \"-c\", \"3\", \"-W\", \"2\", host,\n                                                 stdout=asyncio.subprocess.PIPE,\n                                                 stderr=asyncio.subprocess.DEVNULL)\n        out, _ = await asyncio.wait_for(p.communicate(), 10)\n    except Exception:\n        return None\n    m = re.search(rb\"= [\\d.]+/([\\d.]+)/\", out)\n    return int(float(m.group(1))) if m else None\n\n\nasync def measure(c):\n    \"\"\"TCP 节点测握手；UDP 节点用 ICMP；都不通则退回 VPNGate 自报值并标注来源。\"\"\"\n    if c[\"proto\"] == \"tcp\":\n        ms = await tcp_rtt(c[\"host\"], c[\"port\"])\n        if ms is not None:\n            return ms, \"tcp\"\n    ms = await icmp_rtt(c[\"host\"])\n    if ms is not None:\n        return ms, \"icmp\"\n    if c[\"ping\"] < 9999:\n        return c[\"ping\"], \"vpngate\"\n    return None, \"none\"\n\n\nasync def scan_once(auto=False):\n    loop = asyncio.get_running_loop()\n    SCAN[\"state\"] = \"scanning\"\n    t0 = time.time()\n    try:\n        cands = await loop.run_in_executor(None, fetch_vpngate)\n        uniq = {c[\"ip\"]: c for c in cands if re.fullmatch(r\"\\d{1,3}(\\.\\d{1,3}){3}\", c[\"ip\"])}\n        ips = list(uniq)\n        log(f\"开始扫描 {len(ips)} 个 VPNGate 节点（IP 类型 + 实测延迟）\")\n\n        info = {}\n        for i in range(0, len(ips), 100):\n            for attempt in range(2):\n                try:\n                    for r in await loop.run_in_executor(None, ipapi_batch, ips[i:i + 100]):\n                        if r.get(\"status\") == \"success\":\n                            info[r[\"query\"]] = r\n                    break\n                except Exception as e:\n                    log(f\"ip-api 批量查询失败: {e}\")\n                    await asyncio.sleep(30 if attempt == 0 else 0)\n            await asyncio.sleep(4.5)\n\n        sem = asyncio.Semaphore(30)\n\n        async def one(ip):\n            c, r = uniq[ip], info[ip]\n            async with sem:\n                ms, method = await measure(c)\n            hosting, mobile = bool(r.get(\"hosting\")), bool(r.get(\"mobile\"))\n            return dict(ip=ip, host=c[\"host\"], port=c[\"port\"], proto=c[\"proto\"], cc=c[\"cc\"],\n                        country=r.get(\"country\", \"\"), region=r.get(\"regionName\", \"\"), city=r.get(\"city\", \"\"),\n                        isp=r.get(\"isp\", \"\"), org=r.get(\"org\", \"\"), hosting=hosting,\n                        proxy=bool(r.get(\"proxy\")), mobile=mobile,\n                        residential=not hosting and not mobile,\n                        latency=ms, method=method, score=c[\"score\"], speed=c[\"speed\"],\n                        sessions=c.get(\"sessions\", 0), users=c.get(\"users\", 0), uptime=c.get(\"uptime\", 0))\n\n        items = [x for x in await asyncio.gather(*(one(ip) for ip in ips if ip in info))]\n        SCAN[\"res\"] = {x[\"ip\"]: (x[\"latency\"] if x[\"latency\"] is not None else 9999)\n                       for x in items if x[\"residential\"]}\n        SCAN[\"bad\"] = {x[\"ip\"] for x in items if x[\"hosting\"]}\n\n        scan_id = int(time.time() * 1000)\n        chunks = [items[i:i + 80] for i in range(0, len(items), 80)] or [[]]\n        for n, chunk in enumerate(chunks):\n            await loop.run_in_executor(None, hub_post, \"/api/agent/scan\", dict(\n                node_id=NODE_ID, scan_id=scan_id, items=chunk, last=n == len(chunks) - 1))\n        SCAN[\"ts\"] = int(time.time() * 1000)\n        if auto:\n            consider_best(list(uniq.values()))\n        ok = sum(1 for x in items if x[\"residential\"] and x[\"latency\"] is not None)\n        log(f\"扫描完成：{len(items)} 条，可达住宅 IP {ok} 条，用时 {int(time.time() - t0)}s\")\n    finally:\n        SCAN[\"state\"] = \"idle\"\n\n\ndef consider_best(cands):\n    \"\"\"定时择优：扫描完成后，若当前隧道不是最优，就切到最优 IP（固定 IP / 关闭自动择优 / 隧道未就绪时不动）。\"\"\"\n    if not S[\"auto_best\"] or S[\"pin\"] or S[\"status\"] != \"up\" or not S[\"cur\"]:\n        return\n    want = S[\"country\"]\n    pool = [c for c in cands\n            if (want == \"ANY\" or c[\"cc\"] == want) and c[\"cc\"] not in S[\"exclude\"]\n            and c[\"ip\"] not in SCAN[\"bad\"] and SCAN[\"res\"].get(c[\"ip\"], 9999) < 9999]\n    if not pool:\n        return\n    best, cur = min(pool, key=route_key), S[\"cur\"]\n    if best[\"ip\"] != cur[\"ip\"] and route_key(best) < route_key(cur):\n        S[\"want_ip\"] = best[\"ip\"]\n        log(f\"定时择优：{best['ip']} ({best['cc']}) 优于当前 {cur['ip']} ({cur['cc']})，切换\")\n        rotate_ev.set()\n    else:\n        log(f\"定时择优：当前 {cur['ip']} 仍是最优，不切换\")\n\n\nasync def scan_loop():\n    await asyncio.sleep(5)\n    auto = False\n    while True:\n        scan_ev.clear()\n        t0 = time.time()\n        try:\n            await scan_once(auto)\n        except Exception as e:\n            log(f\"扫描失败: {e}\")\n        try:  # 以「开始时间」起算，保证约每 SCAN_INTERVAL 秒一轮\n            await asyncio.wait_for(scan_ev.wait(), max(30, SCAN_INTERVAL - (time.time() - t0)))\n            auto = False  # 面板手动触发：只刷新数据，不自动换线\n        except asyncio.TimeoutError:\n            auto = True\n\n\nasync def sh(*cmd):\n    p = await asyncio.create_subprocess_exec(*cmd, stdout=asyncio.subprocess.DEVNULL,\n                                             stderr=asyncio.subprocess.DEVNULL)\n    return await p.wait()\n\n\nasync def cleanup_routes():\n    for _ in range(3):\n        await sh(\"ip\", \"rule\", \"del\", \"oif\", DEV, \"lookup\", TABLE)\n    await sh(\"ip\", \"route\", \"flush\", \"table\", TABLE)\n\n\nasync def start_vpn(c):\n    keep = [l for l in c[\"text\"].splitlines()\n            if not l.startswith((\"dev \", \"dev-type\", \"script-security\", \"up \", \"down \", \"redirect-gateway\"))]\n    keep += [f\"dev {DEV}\", \"dev-type tun\", \"route-nopull\", \"nobind\",\n             \"data-ciphers AES-256-GCM:AES-128-GCM:AES-128-CBC\", \"data-ciphers-fallback AES-128-CBC\", \"verb 3\"]\n    path = os.path.join(WORKDIR, \"current.ovpn\")\n    with open(path, \"w\") as f:\n        f.write(\"\\n\".join(keep) + \"\\n\")\n    proc = await asyncio.create_subprocess_exec(\"openvpn\", \"--config\", path,\n                                                stdout=asyncio.subprocess.PIPE,\n                                                stderr=asyncio.subprocess.STDOUT)\n\n    async def wait_ready():\n        while True:\n            line = await proc.stdout.readline()\n            if not line:\n                return False\n            if b\"Initialization Sequence Completed\" in line:\n                return True\n\n    try:\n        ok = await asyncio.wait_for(wait_ready(), 30)\n    except asyncio.TimeoutError:\n        ok = False\n\n    async def drain():\n        while await proc.stdout.readline():\n            pass\n\n    if ok:\n        asyncio.create_task(drain())\n    return proc, ok\n\n\nasync def stop_vpn(proc):\n    if proc and proc.returncode is None:\n        proc.terminate()\n        try:\n            await asyncio.wait_for(proc.wait(), 5)\n        except asyncio.TimeoutError:\n            proc.kill()\n    await cleanup_routes()\n    S.update(exit_ip=\"\", cc=\"\", isp=\"\", hosting=False, latency=0)\n\n\nasync def verify(c):\n    \"\"\"路由 + 出口质检；通过才算可用。\"\"\"\n    await cleanup_routes()\n    await sh(\"ip\", \"route\", \"replace\", \"default\", \"dev\", DEV, \"table\", TABLE)\n    await sh(\"ip\", \"rule\", \"add\", \"oif\", DEV, \"lookup\", TABLE, \"priority\", \"100\")\n    loop = asyncio.get_running_loop()\n    try:\n        info = await loop.run_in_executor(None, ident)\n    except Exception as e:\n        log(f\"出口检测失败: {e}\")\n        return False\n    if info.get(\"status\") != \"success\":\n        log(\"出口检测无结果\")\n        return False\n    if S[\"pin\"]:\n        if info.get(\"hosting\"):\n            log(f\"提示：固定的出口 {info['query']} 被判定为机房 IP\")\n    elif info.get(\"countryCode\") in S[\"exclude\"]:\n        log(f\"出口国家 {info['countryCode']} 在排除列表中，跳过\")\n        return False\n    elif S[\"country\"] != \"ANY\" and info[\"countryCode\"] != S[\"country\"]:\n        log(f\"出口国家 {info['countryCode']} 与目标 {S['country']} 不符\")\n        return False\n    if info.get(\"hosting\") and not ALLOW_HOSTING and not S[\"pin\"]:\n        log(f\"出口 {info['query']} 被判定为机房 IP，跳过\")\n        return False\n    S.update(exit_ip=info[\"query\"], cc=info[\"countryCode\"], isp=info.get(\"isp\", \"\"),\n             hosting=bool(info.get(\"hosting\")), latency=await loop.run_in_executor(None, probe) or 0)\n    return True\n\n\nasync def monitor(proc):\n    loop = asyncio.get_running_loop()\n    fails, tick = 0, 0\n    while True:\n        try:\n            await asyncio.wait_for(rotate_ev.wait(), 5)\n            return \"换 IP / 策略变更\"\n        except asyncio.TimeoutError:\n            pass\n        if proc.returncode is not None:\n            return \"openvpn 已退出\"\n        tick += 1\n        if tick % 3 == 0:\n            ms = await loop.run_in_executor(None, probe)\n            if ms is None:\n                fails += 1\n                if fails >= 2:\n                    return \"探测连续失败\"\n            else:\n                fails, S[\"latency\"] = 0, ms\n\n\ndef route_key(c):\n    \"\"\"路由排序：已扫描确认的住宅 IP 永远排在前面，再按模式排。\n    country = 评分优先（默认）  latency = 实测延迟最低  speed = VPNGate 测速最高\"\"\"\n    lat = SCAN[\"res\"].get(c[\"ip\"])\n    known = lat is not None\n    lat_v = lat if known else 99999 + c[\"ping\"]\n    if S[\"mode\"] == \"speed\":\n        return (c[\"cc\"] not in S[\"prefer\"], not known, -c[\"speed\"], lat_v, -c[\"score\"])\n    if S[\"mode\"] == \"latency\":\n        return (c[\"cc\"] not in S[\"prefer\"], not known, lat_v, -c[\"speed\"], -c[\"score\"])\n    return (c[\"cc\"] not in S[\"prefer\"], not known, -c[\"score\"], lat_v, c[\"ping\"])\n\n\nasync def tunnel_loop():\n    black, cache, cache_t = set(), [], 0\n    while True:\n        S[\"status\"] = \"connecting\"\n        want = S[\"country\"]\n        try:\n            if not cache or time.time() - cache_t > 600:\n                cache = await asyncio.get_running_loop().run_in_executor(None, fetch_vpngate)\n                cache_t = time.time()\n                log(f\"VPNGate 节点列表 {len(cache)} 条\")\n        except Exception as e:\n            log(f\"拉取 VPNGate 失败: {e}\")\n            await asyncio.sleep(30)\n            continue\n        pin = S[\"pin\"]\n        if S[\"want_ip\"]:  # 定时择优：最优 IP 与上一条线路都放回候选\n            black.discard(S[\"want_ip\"])\n            black.discard(S[\"last_ip\"])\n        if not pin:\n            log(f\"路由模式: {ROUTE_NAMES[S['mode']]}，目标 {'全球' if want == 'ANY' else want}\"\n                + (f\"，优先 {','.join(sorted(S['prefer']))}\" if S[\"prefer\"] else \"\")\n                + (f\"，排除 {','.join(sorted(S['exclude']))}\" if S[\"exclude\"] else \"\"))\n        if pin:\n            cands = [c for c in cache if c[\"ip\"] == pin]\n            if not cands and time.time() - cache_t > 60:\n                cache_t = 0  # 列表可能过期，刷新一次再判断\n                continue\n        else:\n            cands = [c for c in cache if (want == \"ANY\" or c[\"cc\"] == want) and c[\"ip\"] not in black\n                     and c[\"cc\"] not in S[\"exclude\"]]\n        if not pin and not ALLOW_HOSTING:\n            cands = [c for c in cands if c[\"ip\"] not in SCAN[\"bad\"]]  # 扫描已确认是机房 IP，不浪费建链时间\n        cands.sort(key=route_key)\n        if S[\"want_ip\"] and not pin:\n            first = [c for c in cands if c[\"ip\"] == S[\"want_ip\"]]\n            if first:\n                cands = first + [c for c in cands if c[\"ip\"] != S[\"want_ip\"]]\n        S[\"want_ip\"] = \"\"\n        if pin and not cands:\n            log(f\"固定的 {pin} 已不在 VPNGate 列表，恢复自动选择\")\n            S[\"pin_fail\"], S[\"pin\"] = pin, \"\"\n            continue\n        alive = await asyncio.gather(*(tcp_alive(c) for c in cands[:40]))\n        cands = [c for c, ok in zip(cands[:40], alive) if ok]\n        if pin and not cands:\n            log(f\"固定的 {pin} 无法连通，恢复自动选择\")\n            S[\"pin_fail\"], S[\"pin\"] = pin, \"\"\n            continue\n        if not cands:\n            log(f\"{want} 暂无可用候选，30 秒后重试\")\n            black.clear()\n            cache_t = 0\n            await asyncio.sleep(30)\n            continue\n        connected = False\n        for c in cands:\n            if S[\"country\"] != want or S[\"pin\"] != pin:\n                break\n            log(f\"尝试 {c['ip']} ({c['cc']}, {c['proto']}/{c['port']})\")\n            proc = None\n            try:\n                proc, ok = await start_vpn(c)\n                if ok and await verify(c):\n                    S[\"status\"] = \"up\"\n                    S[\"cur\"], S[\"last_ip\"] = c, c[\"ip\"]\n                    connected = True\n                    log(f\"隧道就绪: 出口 {S['exit_ip']} {S['cc']} {S['isp']} {S['latency']}ms\")\n                    reason = await monitor(proc)\n                    log(f\"隧道结束: {reason}\")\n                    rotate_ev.clear()\n            finally:\n                await stop_vpn(proc)\n                S[\"cur\"] = None\n            black.add(c[\"ip\"])\n            S[\"status\"] = \"connecting\"\n            if pin and S[\"pin\"] == pin and not connected:\n                log(f\"固定的 {pin} 连接 / 质检失败，恢复自动选择\")\n                S[\"pin_fail\"], S[\"pin\"] = pin, \"\"\n                break\n\n\n\n# ---------------------------------------------------------------- 系统诊断\ndef _run(cmd, timeout=8):\n    try:\n        r = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout)\n        return r.returncode, (r.stdout + r.stderr)\n    except Exception as e:\n        return -1, str(e)\n\n\ndef _timed(fn):\n    t = time.time()\n    try:\n        return True, fn(), int((time.time() - t) * 1000)\n    except Exception as e:\n        return False, str(e), int((time.time() - t) * 1000)\n\n\ndef diag_local():\n    out = []\n\n    def add(i, name, st, detail=\"\", ms=None):\n        out.append(dict(id=i, name=name, status=st, detail=str(detail)[:200], ms=ms))\n\n    root = hasattr(os, \"geteuid\") and os.geteuid() == 0\n    add(\"root\", \"运行身份\", \"ok\" if root else \"fail\", \"root\" if root else \"需要 root（SO_BINDTODEVICE / ip rule）\")\n    tun = os.path.exists(\"/dev/net/tun\") and os.access(\"/dev/net/tun\", os.R_OK | os.W_OK)\n    add(\"tun\", \"TUN/TAP 设备\", \"ok\" if tun else \"fail\", \"/dev/net/tun 可用\" if tun else \"缺少 /dev/net/tun，请在 VPS 控制台开启 TUN/TAP\")\n    py = sys.version_info\n    add(\"python\", \"Python 版本\", \"ok\" if py >= (3, 9) else \"fail\", f\"{py.major}.{py.minor}.{py.micro}\")\n    for tool in (\"openvpn\", \"ip\", \"ping\"):\n        path = shutil.which(tool)\n        add(\"bin_\" + tool, f\"命令 {tool}\", \"ok\" if path else (\"warn\" if tool == \"ping\" else \"fail\"),\n            path or (\"未安装\" + (\"，UDP 节点将无法实测延迟\" if tool == \"ping\" else \"\")))\n    if shutil.which(\"openvpn\"):\n        rc, o = _run([\"openvpn\", \"--version\"])\n        m = re.search(r\"OpenVPN (\\d+)\\.(\\d+)\", o)\n        if m:\n            ok = (int(m.group(1)), int(m.group(2))) >= (2, 5)\n            add(\"ovpn_ver\", \"OpenVPN 版本\", \"ok\" if ok else \"fail\", f\"{m.group(1)}.{m.group(2)}\" + (\"\" if ok else \"，需要 >= 2.5\"))\n    try:\n        load = os.getloadavg()[0]\n        cpus = os.cpu_count() or 1\n        add(\"load\", \"系统负载\", \"ok\" if load < cpus * 1.5 else \"warn\", f\"1 分钟负载 {load:.2f}（{cpus} 核）\")\n    except Exception:\n        pass\n    try:\n        mem = {k: int(v.split()[0]) for k, v in (l.split(\":\", 1) for l in open(\"/proc/meminfo\"))}\n        avail = mem.get(\"MemAvailable\", 0) // 1024\n        add(\"mem\", \"可用内存\", \"ok\" if avail > 100 else \"warn\", f\"{avail} MB 可用 / {mem.get('MemTotal', 0) // 1024} MB\")\n    except Exception:\n        pass\n    try:\n        free = shutil.disk_usage(WORKDIR if os.path.isdir(WORKDIR) else \"/\").free // (1024 * 1024)\n        add(\"disk\", \"磁盘空间\", \"ok\" if free > 200 else \"warn\", f\"{free} MB 可用\")\n    except Exception:\n        pass\n    skew = abs(S[\"skew\"]) / 1000\n    add(\"clock\", \"系统时钟\", \"ok\" if skew < 60 else (\"warn\" if skew < 300 else \"fail\"),\n        f\"与面板相差 {skew:.0f} 秒\" + (\"\" if skew < 60 else \"（时间偏差会导致证书 / 握手失败，请校时）\"))\n    add(\"hub\", \"面板连通\", \"ok\" if 0 < S[\"hub_rtt\"] < 2000 else \"warn\", f\"心跳往返 {S['hub_rtt']} ms\", S[\"hub_rtt\"])\n    return out\n\n\ndef diag_net():\n    out = []\n\n    def add(i, name, ok, detail, ms, warn=False):\n        out.append(dict(id=i, name=name, status=\"ok\" if ok else (\"warn\" if warn else \"fail\"), detail=str(detail)[:200], ms=ms))\n\n    ok, v, ms = _timed(lambda: socket.getaddrinfo(\"www.vpngate.net\", 80)[0][4][0])\n    add(\"dns\", \"系统 DNS 解析\", ok, v if ok else \"解析 www.vpngate.net 失败：\" + v, ms)\n\n    def vg():\n        req = urllib.request.Request(VPNGATE_API, headers={\"User-Agent\": \"Mozilla/5.0\"})\n        d = urllib.request.urlopen(req, timeout=12).read(4096)\n        if not d:\n            raise OSError(\"空响应\")\n        return f\"收到 {len(d)}B 起始数据\"\n    ok, v, ms = _timed(vg)\n    add(\"vpngate\", \"VPNGate API\", ok, v, ms)\n\n    def ia():\n        d = json.loads(urllib.request.urlopen(\"http://ip-api.com/json/?fields=status,query,country\", timeout=8).read())\n        if d.get(\"status\") != \"success\":\n            raise OSError(\"返回失败\")\n        return f\"{d.get('query')} {d.get('country', '')}\"\n    ok, v, ms = _timed(ia)\n    add(\"ipapi\", \"ip-api 质检接口\", ok, v, ms)\n\n    ok, v, ms = _timed(lambda: get_public_ip() or (_ for _ in ()).throw(OSError(\"无法获取\")))\n    add(\"pubip\", \"VPS 公网 IP\", ok, v, ms)\n    return out\n\n\nasync def proxy_selftest():\n    \"\"\"用本机凭据走一遍完整 SOCKS5 流程：握手 -> 认证 -> 经隧道访问外网，返回看到的出口 IP。\"\"\"\n    if not S[\"user\"] or not S[\"pw\"]:\n        raise OSError(\"未配置代理凭据\")\n    r, w = await asyncio.wait_for(asyncio.open_connection(\"127.0.0.1\", S[\"port\"]), 5)\n    try:\n        w.write(b\"\\x05\\x01\\x02\")\n        if await asyncio.wait_for(r.readexactly(2), 5) != b\"\\x05\\x02\":\n            raise OSError(\"SOCKS5 握手被拒绝\")\n        u, pw = S[\"user\"].encode(), S[\"pw\"].encode()\n        w.write(b\"\\x01\" + bytes([len(u)]) + u + bytes([len(pw)]) + pw)\n        if await asyncio.wait_for(r.readexactly(2), 5) != b\"\\x01\\x00\":\n            raise OSError(\"认证失败\")\n        host = b\"api.ipify.org\"\n        w.write(b\"\\x05\\x01\\x00\\x03\" + bytes([len(host)]) + host + struct.pack(\"!H\", 80))\n        rep = await asyncio.wait_for(r.readexactly(10), 15)\n        if rep[1] != 0:\n            raise OSError(f\"隧道连接失败（SOCKS 应答码 {rep[1]}）\")\n        w.write(b\"GET / HTTP/1.0\\r\\nHost: api.ipify.org\\r\\n\\r\\n\")\n        await w.drain()\n        data = await asyncio.wait_for(r.read(4096), 10)\n        return data.split(b\"\\r\\n\\r\\n\")[-1].strip().decode(\"ascii\", \"ignore\")\n    finally:\n        w.close()\n\n\nasync def diag_once():\n    loop = asyncio.get_running_loop()\n    DIAG[\"running\"] = True\n    log(\"开始系统诊断\")\n    try:\n        items = await loop.run_in_executor(None, diag_local)\n        items += await loop.run_in_executor(None, diag_net)\n\n        def add(i, name, st, detail=\"\", ms=None):\n            items.append(dict(id=i, name=name, status=st, detail=str(detail)[:200], ms=ms))\n\n        up = S[\"status\"] == \"up\"\n        add(\"tunnel\", \"隧道状态\", \"ok\" if up else (\"warn\" if S[\"status\"] == \"connecting\" else \"fail\"),\n            f\"{S['exit_ip']} {S['cc']} {S['isp']}\".strip() if up else f\"当前状态：{S['status']}\")\n        if up:\n            ms = await loop.run_in_executor(None, probe)\n            add(\"tun_probe\", \"隧道出站 (1.1.1.1:443)\", \"ok\" if ms is not None else \"fail\",\n                \"连通\" if ms is not None else \"经隧道无法出站\", ms)\n            ok, v, ms2 = await loop.run_in_executor(None, _timed, lambda: tun_resolve(\"example.com\"))\n            add(\"tun_dns\", \"隧道内 DNS\", \"ok\" if ok else \"fail\", v, ms2)\n            rc, o = await loop.run_in_executor(None, _run, [\"ip\", \"rule\", \"show\"])\n            has = DEV in o\n            add(\"route\", \"策略路由\", \"ok\" if has else \"fail\", f\"ip rule 含 {DEV}\" if has else \"缺少 oif tun_rp 的策略路由\")\n        add(\"route_mode\", \"路由模式\", \"ok\", f\"{ROUTE_NAMES[S['mode']]}，目标 {S['country']}\" + (f\"，已固定 {S['pin']}\" if S[\"pin\"] else \"\"))\n        add(\"scan\", \"住宅 IP 扫描\", \"ok\" if SCAN[\"ts\"] else \"warn\",\n            f\"{len(SCAN['res'])} 个住宅 IP，{int((time.time() * 1000 - SCAN['ts']) / 60000)} 分钟前\" if SCAN[\"ts\"] else \"尚未完成首次扫描\")\n\n        if not S[\"proxy_on\"]:\n            add(\"proxy\", \"代理服务\", \"warn\", \"已在面板停用\")\n        else:\n            ok, v, ms = await loop.run_in_executor(None, _timed, lambda: socket.create_connection((\"127.0.0.1\", S[\"port\"]), 3).close())\n            add(\"proxy\", \"代理监听\", \"ok\" if ok else \"fail\", f\"127.0.0.1:{S['port']} 可连接\" if ok else f\"本机无法连接 :{S['port']}\", ms)\n            add(\"proxy_auth\", \"代理凭据\", \"ok\" if S[\"user\"] and S[\"pw\"] else \"fail\",\n                \"已配置\" if S[\"user\"] and S[\"pw\"] else \"PROXY_USER / PROXY_PASS 未配置，所有连接都会被拒绝\")\n            if ok and up:\n                t = time.time()\n                try:\n                    ip = await proxy_selftest()\n                    same = ip == S[\"exit_ip\"]\n                    add(\"proxy_e2e\", \"代理端到端自测\", \"ok\", f\"经代理看到出口 {ip}\" + (\"（与质检一致）\" if same else \"（与质检出口不同，可能是多出口节点）\"),\n                        int((time.time() - t) * 1000))\n                except Exception as e:\n                    add(\"proxy_e2e\", \"代理端到端自测\", \"fail\", str(e) or type(e).__name__, int((time.time() - t) * 1000))\n        add(\"conns\", \"连接数\", \"warn\" if PROXY[\"active\"] >= S[\"max_conns\"] * 0.9 else \"ok\",\n            f\"当前 {PROXY['active']} / 上限 {S['max_conns']}，累计 {PROXY['total']}，拒绝 {PROXY['rejected']}\")\n\n        DIAG[\"ts\"] = int(time.time() * 1000)\n        await loop.run_in_executor(None, hub_post, \"/api/agent/diag\", dict(node_id=NODE_ID, items=items))\n        bad = sum(1 for x in items if x[\"status\"] == \"fail\")\n        warn = sum(1 for x in items if x[\"status\"] == \"warn\")\n        log(f\"诊断完成：{len(items)} 项，失败 {bad}，警告 {warn}\")\n    finally:\n        DIAG[\"running\"] = False\n\n\nasync def diag_loop():\n    await asyncio.sleep(20)  # 启动后自动跑一次\n    while True:\n        diag_ev.clear()\n        try:\n            await diag_once()\n        except Exception as e:\n            log(f\"诊断失败: {e}\")\n        await diag_ev.wait()\n\n\n# ---------------------------------------------------------------- proxy server (SOCKS5 + HTTP, 同端口)\ndef auth_ok(user, pw):\n    if not S[\"user\"] or not S[\"pw\"]:\n        return False  # 未配置凭据一律拒绝，避免变成开放代理\n    a = hmac.compare_digest(user.encode(), S[\"user\"].encode())\n    b = hmac.compare_digest(pw.encode(), S[\"pw\"].encode())\n    return a and b\n\n\nasync def open_out(host, port):\n    if S[\"status\"] != \"up\":\n        raise OSError(\"tunnel down\")\n    loop = asyncio.get_running_loop()\n    ip = await loop.run_in_executor(None, tun_resolve, host)\n    a = ipaddress.ip_address(ip)\n    if a.version != 4 or not a.is_global:\n        raise OSError(\"blocked address\")\n    s = tun_sock()\n    s.setblocking(False)\n    try:\n        await asyncio.wait_for(loop.sock_connect(s, (ip, port)), 15)\n    except BaseException:\n        s.close()\n        raise\n    return await asyncio.open_connection(sock=s)\n\n\ndef proxy_stats():\n    return dict(on=S[\"proxy_on\"], listening=PROXY[\"listening\"], port=S[\"port\"], active=PROXY[\"active\"],\n                total=PROXY[\"total\"], rejected=PROXY[\"rejected\"], up=PROXY[\"up\"], down=PROXY[\"down\"],\n                since=PROXY[\"since\"], max=S[\"max_conns\"])\n\n\nasync def pipe(r, w, key=None):\n    try:\n        while True:\n            d = await asyncio.wait_for(r.read(65536), 300)\n            if not d:\n                break\n            if key:\n                PROXY[key] += len(d)\n            w.write(d)\n            await w.drain()\n    except Exception:\n        pass\n    finally:\n        try:\n            w.close()\n        except Exception:\n            pass\n\n\nasync def relay(cr, cw, rr, rw):\n    await asyncio.gather(pipe(cr, rw, \"up\"), pipe(rr, cw, \"down\"))\n\n\nasync def socks5(cr, cw):\n    n = (await cr.readexactly(1))[0]\n    methods = await cr.readexactly(n)\n    if 2 not in methods:\n        cw.write(b\"\\x05\\xff\")\n        return\n    cw.write(b\"\\x05\\x02\")\n    await cr.readexactly(1)\n    user = await cr.readexactly((await cr.readexactly(1))[0])\n    pw = await cr.readexactly((await cr.readexactly(1))[0])\n    if not auth_ok(user.decode(\"utf-8\", \"ignore\"), pw.decode(\"utf-8\", \"ignore\")):\n        cw.write(b\"\\x01\\x01\")\n        return\n    cw.write(b\"\\x01\\x00\")\n    _ver, cmd, _rsv, atyp = await cr.readexactly(4)\n    if cmd != 1:\n        cw.write(b\"\\x05\\x07\\x00\\x01\\0\\0\\0\\0\\0\\0\")\n        return\n    if atyp == 1:\n        host = socket.inet_ntoa(await cr.readexactly(4))\n    elif atyp == 3:\n        host = (await cr.readexactly((await cr.readexactly(1))[0])).decode(\"utf-8\", \"ignore\")\n    else:\n        cw.write(b\"\\x05\\x08\\x00\\x01\\0\\0\\0\\0\\0\\0\")\n        return\n    port = struct.unpack(\"!H\", await cr.readexactly(2))[0]\n    try:\n        rr, rw = await open_out(host, port)\n    except Exception:\n        cw.write(b\"\\x05\\x04\\x00\\x01\\0\\0\\0\\0\\0\\0\")\n        return\n    cw.write(b\"\\x05\\x00\\x00\\x01\\0\\0\\0\\0\\0\\0\")\n    await cw.drain()\n    await relay(cr, cw, rr, rw)\n\n\nasync def http_proxy(first, cr, cw):\n    head = first + await asyncio.wait_for(cr.readuntil(b\"\\r\\n\\r\\n\"), 10)\n    lines = head.split(b\"\\r\\n\")\n    method, target, ver = lines[0].decode(\"latin1\").split(\" \", 2)\n    hdrs, auth = [], \"\"\n    for l in lines[1:]:\n        if not l:\n            continue\n        k, _, v = l.decode(\"latin1\").partition(\":\")\n        kl = k.strip().lower()\n        if kl == \"proxy-authorization\":\n            auth = v.strip()\n        elif kl not in (\"proxy-connection\", \"connection\"):\n            hdrs.append((k.strip(), v.strip()))\n    ok = False\n    if auth.lower().startswith(\"basic \"):\n        try:\n            u, _, p = base64.b64decode(auth[6:]).decode(\"utf-8\", \"ignore\").partition(\":\")\n            ok = auth_ok(u, p)\n        except Exception:\n            pass\n    if not ok:\n        cw.write(b'HTTP/1.1 407 Proxy Authentication Required\\r\\nProxy-Authenticate: Basic realm=\"proxy\"\\r\\n'\n                 b\"Content-Length: 0\\r\\nConnection: close\\r\\n\\r\\n\")\n        return\n    try:\n        if method == \"CONNECT\":\n            host, _, port = target.rpartition(\":\")\n            rr, rw = await open_out(host.strip(\"[]\"), int(port))\n            cw.write(b\"HTTP/1.1 200 Connection Established\\r\\n\\r\\n\")\n        else:\n            u = urlsplit(target)\n            rr, rw = await open_out(u.hostname, u.port or 80)\n            path = (u.path or \"/\") + (\"?\" + u.query if u.query else \"\")\n            out = f\"{method} {path} {ver}\\r\\n\" + \"\".join(f\"{k}: {v}\\r\\n\" for k, v in hdrs) + \"Connection: close\\r\\n\\r\\n\"\n            rw.write(out.encode(\"latin1\"))\n    except Exception:\n        cw.write(b\"HTTP/1.1 502 Bad Gateway\\r\\nContent-Length: 0\\r\\nConnection: close\\r\\n\\r\\n\")\n        return\n    await relay(cr, cw, rr, rw)\n\n\nasync def handle(cr, cw):\n    if PROXY[\"active\"] >= S[\"max_conns\"]:\n        PROXY[\"rejected\"] += 1\n        try:\n            cw.close()\n        except Exception:\n            pass\n        return\n    PROXY[\"active\"] += 1\n    PROXY[\"total\"] += 1\n    try:\n        first = await asyncio.wait_for(cr.readexactly(1), 10)\n        if first == b\"\\x05\":\n            await socks5(cr, cw)\n        else:\n            await http_proxy(first, cr, cw)\n    except Exception:\n        pass\n    finally:\n        PROXY[\"active\"] -= 1\n        try:\n            cw.close()\n        except Exception:\n            pass\n\n\nasync def proxy_supervisor():\n    while True:\n        port_ev.clear()\n        PROXY[\"listening\"] = False\n        if not S[\"proxy_on\"]:\n            await port_ev.wait()\n            continue\n        port = S[\"port\"]\n        try:\n            srv = await asyncio.start_server(handle, \"0.0.0.0\", port)\n        except OSError as e:\n            log(f\"监听 :{port} 失败: {e}\")\n            await asyncio.sleep(10)\n            continue\n        PROXY[\"listening\"], PROXY[\"since\"] = True, int(time.time() * 1000)\n        log(f\"代理监听 :{port}（SOCKS5 / HTTP，需认证）\")\n        await port_ev.wait()\n        srv.close()\n        PROXY[\"listening\"] = False\n\n\nasync def main():\n    global rotate_ev, port_ev, scan_ev, diag_ev\n    rotate_ev, port_ev, scan_ev, diag_ev = asyncio.Event(), asyncio.Event(), asyncio.Event(), asyncio.Event()\n    os.makedirs(WORKDIR, exist_ok=True)\n    await cleanup_routes()\n    asyncio.create_task(heartbeat_loop())\n    while not S[\"ready\"]:\n        await asyncio.sleep(1)\n    await asyncio.gather(proxy_supervisor(), tunnel_loop(), scan_loop(), diag_loop())\n\n\nif __name__ == \"__main__\":\n    asyncio.run(main())\n";
export const INSTALL_SH = "#!/usr/bin/env bash\n# resi-agent 一键安装（由 Worker 渲染，__HUB__ / __TOKEN__ 在下发时替换）\nset -euo pipefail\nHUB=\"__HUB__\"\nTOKEN=\"__TOKEN__\"\n\n[ \"$(id -u)\" = 0 ] || { echo \"请用 root 运行\"; exit 1; }\n[ -c /dev/net/tun ] || { echo \"缺少 /dev/net/tun，请先在 VPS 控制台开启 TUN/TAP\"; exit 1; }\n\nif command -v apt-get >/dev/null 2>&1; then\n  apt-get update -y && apt-get install -y openvpn python3 iproute2 curl iputils-ping\nelif command -v dnf >/dev/null 2>&1; then\n  dnf install -y epel-release || true\n  dnf install -y openvpn python3 iproute curl iputils\nelse\n  echo \"仅支持 Debian/Ubuntu/RHEL 系\"; exit 1\nfi\n\nver=\"$(openvpn --version | head -1 | awk '{print $2}')\"\nif [ \"$(printf '%s\\n2.5.0\\n' \"$ver\" | sort -V | head -1)\" != \"2.5.0\" ]; then\n  echo \"OpenVPN $ver 过旧，需要 >= 2.5（建议 Debian 11+/Ubuntu 22.04+）\"; exit 1\nfi\n\ninstall -d -m 700 /opt/resi-agent\ncurl -fsSL -H \"Authorization: Bearer $TOKEN\" \"$HUB/agent.py\" -o /opt/resi-agent/agent.py\n\ncat > /etc/resi-agent.env <<ENV\nHUB_URL=$HUB\nAGENT_TOKEN=$TOKEN\nNODE_ID=$(hostname)\nENV\nchmod 600 /etc/resi-agent.env\n\ncat > /etc/systemd/system/resi-agent.service <<'UNIT'\n[Unit]\nDescription=resi-agent\nAfter=network-online.target\nWants=network-online.target\n\n[Service]\nEnvironmentFile=/etc/resi-agent.env\nExecStart=/usr/bin/python3 /opt/resi-agent/agent.py\nRestart=always\nRestartSec=5\n\n[Install]\nWantedBy=multi-user.target\nUNIT\n\nsystemctl daemon-reload\nsystemctl enable resi-agent\nsystemctl restart resi-agent\necho \"已安装。查看日志: journalctl -u resi-agent -f\"\necho \"记得在 VPS 防火墙/安全组放行面板里设置的代理端口（默认 7920）。\"\n";
export const UNINSTALL_SH = "#!/usr/bin/env bash\n# resi-agent 完全卸载：停止服务、清理路由 / tun 设备、删除程序与配置\nset -uo pipefail\n\n[ \"$(id -u)\" = 0 ] || { echo \"请用 root 运行\"; exit 1; }\n\necho \"[1/5] 停止并禁用服务\"\nsystemctl stop resi-agent 2>/dev/null || true\nsystemctl disable resi-agent 2>/dev/null || true\n\necho \"[2/5] 结束残留的 openvpn 进程\"\npkill -f \"openvpn --config /opt/resi-agent/current.ovpn\" 2>/dev/null || true\nsleep 1\n\necho \"[3/5] 清理策略路由与 tun 设备\"\nfor _ in 1 2 3; do ip rule del oif tun_rp lookup 100 2>/dev/null || true; done\nip route flush table 100 2>/dev/null || true\nip link del tun_rp 2>/dev/null || true\n\necho \"[4/5] 删除服务文件、配置与程序目录\"\nrm -f /etc/systemd/system/resi-agent.service /etc/resi-agent.env\nrm -rf /opt/resi-agent\nsystemctl daemon-reload\nsystemctl reset-failed 2>/dev/null || true\n\necho \"[5/5] 完成\"\necho \"已完全卸载 resi-agent。依赖包（openvpn / python3 等）未删除，如不需要可自行 apt remove。\"\necho \"请回到面板，在「节点」列表点「删除」移除该节点记录。\"\n";
export const PANEL_HTML = "<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>龍哥代理控制台</title>\n<style>\n:root{\n  --ink:#e6f1f5; --muted:#8fa6b2; --paper:#05080c; --card:#0d1620; --line:rgba(120,200,255,.16);\n  --up:#3ee0c4; --warn:#f0b04a; --down:#ff6b5e; --accent:#2a9df4;\n  --mono:ui-monospace,\"SF Mono\",\"Cascadia Mono\",Menlo,Consolas,monospace;\n  --sans:system-ui,-apple-system,\"Segoe UI\",\"PingFang SC\",\"Microsoft YaHei\",sans-serif;\n  --glass:55%; color-scheme:dark;\n}\n*{box-sizing:border-box}\nbody{margin:0;color:var(--ink);font:15px/1.5 var(--sans);background-color:#05080c;\n  background-image:radial-gradient(900px 520px at 12% -8%,rgba(42,157,244,.22),transparent 60%),\n    radial-gradient(800px 520px at 100% 0%,rgba(130,90,255,.16),transparent 60%),\n    radial-gradient(700px 480px at 50% 110%,rgba(62,224,196,.10),transparent 60%),\n    linear-gradient(rgba(120,200,255,.05) 1px,transparent 1px),\n    linear-gradient(90deg,rgba(120,200,255,.05) 1px,transparent 1px);\n  background-size:auto,auto,auto,44px 44px,44px 44px;background-attachment:fixed}\nhtml{overflow-x:hidden}\nmain{max-width:1200px;margin:0 auto;padding:24px 16px 48px}\nh1{font-size:22px;margin:0 0 4px;font-weight:650;letter-spacing:.01em}\n.sub{color:var(--muted);margin:0 0 20px}\nsection,.head,.stat,.tabs{background:color-mix(in srgb,var(--card) var(--glass),transparent);\n  -webkit-backdrop-filter:blur(16px) saturate(150%);backdrop-filter:blur(16px) saturate(150%);\n  border:1px solid var(--line);box-shadow:0 8px 32px rgba(0,0,0,.38),inset 0 1px 0 rgba(255,255,255,.06)}\nsection{border-radius:10px;padding:16px;margin-bottom:16px;min-width:0}\nh2{font-size:15px;margin:0 0 12px;font-weight:650}\n.warn{border-left:4px solid var(--warn);padding:8px 12px;margin-bottom:16px;background:var(--card);color:var(--ink)}\n.table-wrap{overflow:visible}\ntable{border-collapse:collapse;width:100%;table-layout:auto}\nth,td{text-align:left;padding:7px 8px;border-bottom:1px solid var(--line);overflow-wrap:anywhere;font-size:13.5px;vertical-align:middle}\nth{font-weight:600;color:var(--muted);font-size:13px}\ntd.mono,.mono{font-family:var(--mono);font-size:12.5px;white-space:nowrap}\n.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:6px;background:var(--muted)}\n.dot.up{background:var(--up)} .dot.connecting{background:var(--warn)} .dot.off{background:var(--down)}\n.row{display:flex;gap:12px;flex-wrap:wrap;align-items:end}\nlabel{display:flex;flex-direction:column;gap:4px;font-size:13px;color:var(--muted)}\ninput,textarea{font:inherit;color:var(--ink);background:rgba(0,0,0,.35);border:1px solid var(--line);border-radius:6px;padding:7px 9px}\ninput{width:130px}\ninput,select{max-width:100%}\ntextarea{width:100%;min-height:90px;font-family:var(--mono);font-size:12.5px;resize:vertical;white-space:pre-wrap;overflow-wrap:anywhere}\nbutton{font:inherit;cursor:pointer;color:#fff;background:linear-gradient(135deg,#2a9df4,#5b7cff);border:0;border-radius:6px;padding:7px 14px;transition:filter .15s,box-shadow .15s}\nbutton:hover{filter:brightness(1.12);box-shadow:0 0 14px rgba(42,157,244,.35)}\nbutton.ghost{background:rgba(255,255,255,.03);color:var(--accent);border:1px solid var(--line);padding:4px 10px;font-size:13px}\nbutton.danger{color:var(--down)}\nbutton:focus-visible,input:focus-visible,textarea:focus-visible{outline:2px solid var(--accent);outline-offset:2px}\npre{margin:0;max-height:260px;overflow-x:hidden;overflow-y:auto;white-space:pre-wrap;overflow-wrap:anywhere;font:12.5px/1.6 var(--mono);color:var(--muted)}\n.cmd{display:flex;gap:8px;align-items:center}\n.cmd code{flex:1;min-width:0;white-space:normal;word-break:break-all;background:rgba(0,0,0,.35);border:1px solid var(--line);border-radius:6px;padding:7px 9px;font-family:var(--mono);font-size:12.5px}\n.empty{color:var(--muted);padding:12px 0}\n.flag{color:var(--warn)}\n.badge{display:inline-block;padding:1px 8px;border-radius:10px;font-size:12px;border:1px solid var(--line);color:var(--muted)}\n.badge.res{color:var(--up);border-color:var(--up)} .badge.host{color:var(--warn);border-color:var(--warn)} .badge.mob{color:var(--accent);border-color:var(--accent)}\n.lat-good{color:var(--up)} .lat-mid{color:var(--warn)} .lat-bad{color:var(--down)}\n.cur{background:color-mix(in srgb,var(--up) 12%,transparent)}\n.tag{color:var(--muted);font-size:11px;margin-left:4px}\nselect{font:inherit;color:var(--ink);background:rgba(0,0,0,.35);border:1px solid var(--line);border-radius:6px;padding:7px 9px}\n.stats{display:flex;gap:20px;flex-wrap:wrap;margin:0 0 12px;color:var(--muted);font-size:13px}\n.stats b{color:var(--ink);font-size:18px;display:block;font-weight:650}\n.scroll{max-height:520px;overflow-x:hidden;overflow-y:auto}\nthead th{position:sticky;top:0;background:color-mix(in srgb,var(--card) 85%,transparent);-webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px)}\ndetails.ex{margin-top:12px}\ndetails.ex summary{cursor:pointer;color:var(--ink)}\n.tabs{position:sticky;top:8px;z-index:5;display:flex;gap:6px;flex-wrap:wrap;padding:8px 10px;margin:0 0 12px;border-radius:10px}\n.tabs button{padding:6px 14px;font-size:14px;color:var(--ink)}\n.tabs button.on{background:linear-gradient(135deg,#2a9df4,#5b7cff);color:#fff;border-color:transparent}\nbody.has-bg{background-size:cover;background-position:center;background-attachment:fixed;background-repeat:no-repeat}\nbody.has-bg{--glass:var(--card-a,88%)}\n.head{border-radius:10px;margin-bottom:12px;padding:12px 16px}\n.cc-grid{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px;max-height:180px;overflow-x:hidden;overflow-y:auto}\n.cc-grid label{flex-direction:row;align-items:center;gap:4px;padding:3px 8px;border:1px solid var(--line);border-radius:12px;cursor:pointer;color:var(--ink);font-size:13px}\n.cc-grid label.on{border-color:var(--down);color:var(--down)}\n/* 状态栏 */\n.statusbar{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-bottom:16px}\n.stat{border-radius:10px;padding:10px 14px;min-width:0}\n.stat .k{display:block;font-size:12.5px;color:var(--muted)}\n.stat b{display:block;font-size:24px;line-height:1.3;font-weight:650}\n.stat .s{display:block;font-size:12px;color:var(--muted);overflow-wrap:anywhere;line-height:1.5}\n.stat.bl b{color:var(--down)}\n/* 窄屏：表格改为卡片，不出现横向滚动 */\n@media (max-width:960px){\n  table,thead,tbody,tr,td{display:block;width:100%}\n  thead{display:none}\n  tr{border:1px solid var(--line);border-radius:6px;margin:0 0 10px;padding:4px 10px}\n  td{position:relative;padding:6px 0 6px 36%;border-bottom:1px dashed var(--line);white-space:normal;min-height:30px}\n  td:last-child{border-bottom:0}\n  td::before{content:attr(data-label);position:absolute;left:0;top:6px;width:33%;color:var(--muted);font-size:12.5px}\n  td[data-label=\"\"],td[colspan]{padding-left:0}\n  td[data-label=\"\"]::before,td[colspan]::before{content:none}\n  td.mono,.mono{white-space:normal}\n  .scroll{max-height:none}\n}\n@media (max-width:700px){.statusbar{grid-template-columns:repeat(2,minmax(0,1fr))}}\n</style>\n</head>\n<body>\n<main>\n  <div class=\"head\">\n    <h1>龍哥代理控制台</h1>\n    <p class=\"sub\" style=\"margin-bottom:0\">节点心跳、出口质检、换 IP 与目标国家，都在这里管理。<span class=\"tag\" id=\"ver\"></span></p>\n    <details class=\"ex\" id=\"bg-box\" style=\"margin-top:6px\">\n      <summary>背景设置</summary>\n      <div class=\"row\" style=\"margin-top:8px\">\n        <label>上传图片<input type=\"file\" id=\"bg-file\" accept=\"image/*\" style=\"width:auto\"></label>\n        <label>或填入图片链接（https）<input id=\"bg-url\" placeholder=\"https://example.com/bg.jpg\" style=\"width:260px\" autocomplete=\"off\"></label>\n        <button id=\"bg-apply\">应用链接</button>\n        <label>面板透明度<input type=\"range\" id=\"bg-op\" min=\"40\" max=\"100\" value=\"88\" style=\"width:140px\"></label>\n        <button class=\"ghost\" id=\"bg-reset\">恢复默认</button>\n        <span id=\"bg-msg\" class=\"sub\" style=\"margin:0\"></span>\n      </div>\n      <p class=\"sub\" style=\"margin:8px 0 0;font-size:12.5px\">背景保存在 Cloudflare KV，所有设备打开面板后会自动同步（约 30 秒内）。上传的图片会自动压缩到 1920px 以内。</p>\n    </details>\n  </div>\n\n  <div class=\"statusbar\" id=\"statusbar\">\n    <div class=\"stat\"><span class=\"k\">当前节点总数</span><b id=\"sb-nodes\">-</b><span class=\"s\" id=\"sb-nodes-sub\">&nbsp;</span></div>\n    <div class=\"stat\"><span class=\"k\">当前可用住宅数</span><b id=\"sb-res\">-</b><span class=\"s\" id=\"sb-res-sub\">&nbsp;</span></div>\n    <div class=\"stat\"><span class=\"k\">可用国家 / 地区</span><b id=\"sb-cc\">-</b><span class=\"s\" id=\"sb-cc-sub\">&nbsp;</span></div>\n    <div class=\"stat bl\"><span class=\"k\">黑名单（不连接的国家）</span><b id=\"sb-bl\">-</b><span class=\"s\" id=\"sb-bl-sub\">&nbsp;</span></div>\n  </div>\n\n  <div id=\"old-agent\" class=\"warn\" hidden></div>\n  <div id=\"warn\" class=\"warn\" hidden>代理账号密码尚未配置（PROXY_USER / PROXY_PASS）。未配置时 agent 会拒绝所有代理连接。</div>\n\n  <section>\n    <h2>节点状态</h2>\n    <div class=\"table-wrap\">\n      <table>\n        <thead><tr><th>状态</th><th>节点</th><th>代理入口</th><th>出口 IP</th><th>国家</th><th>ISP</th><th>延迟</th><th>最近心跳</th><th></th></tr></thead>\n        <tbody id=\"nodes\"></tbody>\n      </table>\n    </div>\n    <div id=\"nodes-empty\" class=\"empty\" hidden>还没有节点接入。复制下面的安装命令，在一台海外 Linux VPS 上以 root 执行。</div>\n  </section>\n\n  <section>\n    <h2>VPS 代理服务状态</h2>\n    <div class=\"table-wrap\">\n      <table>\n        <thead><tr><th>节点</th><th>服务</th><th>端口</th><th>当前连接</th><th>累计 / 拒绝</th><th>上行</th><th>下行</th><th>已运行</th></tr></thead>\n        <tbody id=\"proxy-body\"></tbody>\n      </table>\n    </div>\n  </section>\n\n  <nav class=\"tabs\" id=\"tabs\"><button class=\"ghost\" data-t=\"nodes\">可用代理列表</button><button class=\"ghost\" data-t=\"scan\">住宅 IP 扫描</button><button class=\"ghost\" data-t=\"route\">路由与代理服务</button><button class=\"ghost\" data-t=\"diag\">系统诊断</button><button class=\"ghost\" data-t=\"install\">接入 / 卸载</button><button class=\"ghost\" data-t=\"logs\">日志</button></nav>\n\n  <section data-tab=\"scan\">\n    <h2>住宅 IP 扫描</h2>\n    <div class=\"stats\">\n      <div><b id=\"st-res\">-</b>住宅 IP（可达）</div>\n      <div><b id=\"st-total\">-</b>扫描总数</div>\n      <div><b id=\"st-cc\">-</b>覆盖国家 / 地区</div>\n      <div><b id=\"st-time\">-</b>最近扫描</div>\n    </div>\n    <div class=\"row\" style=\"margin-bottom:12px\">\n      <label>国家 / 地区<select id=\"f-cc\"><option value=\"\">全部</option></select></label>\n      <label>类型<select id=\"f-type\">\n        <option value=\"res\">仅住宅</option><option value=\"all\">全部</option>\n        <option value=\"host\">仅机房</option><option value=\"mob\">仅移动网络</option></select></label>\n      <label>延迟上限 (ms)<input id=\"f-lat\" inputmode=\"numeric\" placeholder=\"不限\" autocomplete=\"off\"></label>\n      <label>排序<select id=\"f-sort\"><option value=\"lat\">延迟低→高</option><option value=\"speed\">速度高→低</option><option value=\"score\">评分高→低</option></select></label>\n      <button id=\"scan-now\">立即扫描</button>\n      <button class=\"ghost\" id=\"copy-scan\">复制 IP:端口</button>\n      <span id=\"scan-msg\" class=\"sub\" style=\"margin:0\"></span>\n    </div>\n    <div class=\"table-wrap scroll\">\n      <table>\n        <thead><tr><th>操作</th><th>类型</th><th>IP:端口</th><th>国家 / 地区</th><th>使用人数</th><th>运行时间</th><th>协议</th><th>真实延迟</th><th>速度</th><th>评分</th><th>来源节点</th></tr></thead>\n        <tbody id=\"scan-body\"></tbody>\n      </table>\n    </div>\n    <div id=\"scan-empty\" class=\"empty\" hidden>暂无扫描结果。节点接入后会自动扫描，也可点「立即扫描」。</div>\n    <p class=\"sub\" style=\"margin:10px 0 0;font-size:12.5px\">类型由 ip-api 判定（机房 / 移动 / 其余视为住宅），属尽力而为。延迟为本 VPS 到该 IP 的实测值：TCP 节点测握手，UDP 节点测 ICMP，两者都失败时才退回 VPNGate 自报值（标「自报」）。</p>\n  </section>\n\n  <section data-tab=\"route\">\n    <h2>路由与代理服务</h2>\n    <div class=\"row\">\n      <label>路由模式<select id=\"mode\">\n        <option value=\"country\">指定国家（按评分）</option>\n        <option value=\"latency\">延迟优先</option>\n        <option value=\"speed\">速度优先</option></select></label>\n      <label id=\"country-wrap\">目标国家（两位代码，或 ANY）<input id=\"country\" maxlength=\"3\" autocomplete=\"off\"></label>\n      <label>代理端口<input id=\"port\" inputmode=\"numeric\" autocomplete=\"off\"></label>\n      <label>最大连接数<input id=\"maxc\" inputmode=\"numeric\" autocomplete=\"off\" style=\"width:100px\"></label>\n      <label>代理服务<select id=\"proxy-on\"><option value=\"1\">启用</option><option value=\"0\">停用</option></select></label>\n      <label>定时择优换线<select id=\"auto-best\"><option value=\"1\">开启（每 16 分钟）</option><option value=\"0\">关闭</option></select></label>\n      <button id=\"save\">保存策略</button>\n      <span id=\"save-msg\" class=\"sub\" style=\"margin:0\"></span>\n    </div>\n    <details class=\"ex\" id=\"pf-box\">\n      <summary>优先国家 / 地区（可多选）：<span id=\"pf-sum\">无</span></summary>\n      <div class=\"row\" style=\"margin-top:8px\"><button class=\"ghost\" id=\"pf-na\">北美洲</button><button class=\"ghost\" id=\"pf-clear\">清空</button></div>\n      <div class=\"cc-grid\" id=\"pf-grid\"></div>\n    </details>\n    <details class=\"ex\" id=\"ex-box\">\n      <summary>不连接的国家（可多选）：<span id=\"ex-sum\">无</span></summary>\n      <div class=\"cc-grid\" id=\"ex-grid\"></div>\n      <button class=\"ghost\" id=\"ex-clear\" style=\"margin-top:8px\">清空</button>\n    </details>\n    <p class=\"sub\" style=\"margin:10px 0 0;font-size:12.5px\">只有<b>指定国家</b>模式需要设置目标国家（ANY = 全球），按 VPNGate 评分选择；<b>延迟优先</b>（实测延迟最低）和<b>速度优先</b>（VPNGate 测速最高）在全球范围内挑选，不限国家。选择顺序：<b>先看「优先国家 / 地区」</b>（有勾选时，这些国家的 IP 永远排在前面；它们都连不上才会换别的国家），<b>再按延迟 / 速度</b>，并优先已确认的住宅 IP；三种模式都会跳过「不连接的国家」。<b>定时择优</b>：agent 每 16 分钟重新抓取并测速 VPNGate 节点，若发现比当前线路更优的 IP 就自动切换（会短暂中断 15–60 秒，手动固定的 IP 不会被换掉）。修改后点「保存策略」生效。停用代理服务后不再接受新连接，已建立的连接会自然结束。</p>\n\n    <h2 style=\"margin-top:18px\">路由预览 <span class=\"tag\" id=\"route-tag\"></span></h2>\n    <div class=\"table-wrap\">\n      <table>\n        <thead><tr><th>#</th><th>IP:端口</th><th>国家 / 地区</th><th>真实延迟</th><th>速度</th><th>评分</th><th>来源节点</th></tr></thead>\n        <tbody id=\"route-body\"></tbody>\n      </table>\n    </div>\n    <div id=\"route-empty\" class=\"empty\" hidden>当前模式 + 国家下没有可达的住宅 IP。先完成一次扫描，或换个国家 / 改成 ANY。</div>\n    <div class=\"row\" style=\"margin-top:8px\"><button class=\"ghost\" id=\"reroute\">按当前路由重新选择</button><span id=\"reroute-msg\" class=\"sub\" style=\"margin:0\"></span></div>\n\n  </section>\n\n  <section data-tab=\"diag\">\n    <h2>系统诊断</h2>\n    <div class=\"row\" style=\"margin-bottom:10px\">\n      <button id=\"diag-run\">运行诊断</button>\n      <span id=\"diag-msg\" class=\"sub\" style=\"margin:0\">检查运行环境、网络、隧道、路由、代理服务，并从 Cloudflare 测试代理端口是否对外开放。</span>\n    </div>\n    <div id=\"diag-out\"></div>\n  </section>\n\n  <section data-tab=\"install\">\n    <h2>接入新节点</h2>\n    <div class=\"cmd\"><code id=\"install\"></code><button class=\"ghost\" data-copy=\"install\">复制</button></div>\n    <h2 style=\"margin-top:16px\">完全卸载节点</h2>\n    <p class=\"sub\" style=\"margin:0 0 8px;font-size:12.5px\">在要卸载的 VPS 上用 root 执行：停止服务、清理路由与 tun 设备、删除程序与配置。卸载后回到上方节点列表点「删除」移除记录。</p>\n    <div class=\"cmd\"><code id=\"uninstall\"></code><button class=\"ghost\" data-copy=\"uninstall\">复制</button></div>\n  </section>\n\n  <section data-tab=\"nodes\">\n    <h2>可用代理列表</h2>\n    <div class=\"row\" style=\"margin-bottom:8px\">\n      <button class=\"ghost\" id=\"fmt-socks\">SOCKS5</button>\n      <button class=\"ghost\" id=\"fmt-http\">HTTP</button>\n      <button class=\"ghost\" id=\"copy-list\">复制</button>\n    </div>\n    <textarea id=\"list\" readonly placeholder=\"节点就绪后，这里会列出 scheme://用户:密码@IP:端口\"></textarea>\n  </section>\n\n  <section data-tab=\"logs\">\n    <h2>日志</h2>\n    <pre id=\"logs\"></pre>\n  </section>\n</main>\n\n<script>\nconst $ = (id) => document.getElementById(id);\nlet scheme = \"socks5\", formReady = false;\n\nasync function api(path, body) {\n  const r = await fetch(path, body === undefined ? {} : {\n    method: \"POST\", headers: { \"content-type\": \"application/json\" }, body: JSON.stringify(body)\n  });\n  const j = await r.json().catch(() => ({}));\n  if (!r.ok) throw new Error(j.error || r.statusText);\n  return j;\n}\n\nconst nodeName = (id) => { const n = (window.__nodes || []).find((x) => x.id === id); return (n && n.alias) || id; };\nasync function renameNode(id) {\n  const cur = nodeName(id);\n  const v = prompt(\"节点名称（留空恢复默认：\" + id + \"）\", cur === id ? \"\" : cur);\n  if (v === null) return;\n  try { await api(\"/api/nodes/rename\", { node_id: id, alias: v.trim() }); } catch (e) { alert(\"修改失败：\" + e.message); }\n  refresh();\n}\nfunction nameCell(tr, id) {\n  const td = cell(tr, nodeName(id)); td.title = id;\n  const b = document.createElement(\"button\"); b.className = \"ghost\"; b.textContent = \"✎\"; b.title = \"编辑名称\";\n  b.style.marginLeft = \"6px\"; b.style.padding = \"1px 6px\"; b.onclick = () => renameNode(id);\n  td.appendChild(b); return td;\n}\n\nfunction cell(tr, text, cls) {\n  const td = document.createElement(\"td\");\n  td.textContent = text;\n  if (cls) td.className = cls;\n  tr.appendChild(td);\n  return td;\n}\n\nfunction ago(ms) {\n  const s = Math.max(0, Math.round(ms / 1000));\n  return s < 60 ? s + \" 秒前\" : s < 3600 ? Math.round(s / 60) + \" 分钟前\" : Math.round(s / 3600) + \" 小时前\";\n}\n\nconst cnNames = (() => { try { return new Intl.DisplayNames([\"zh-CN\"], { type: \"region\" }); } catch { return null; } })();\nconst cname = (cc, fallback) => { try { return (cc && cnNames && cnNames.of(cc)) || fallback || cc || \"-\"; } catch { return fallback || cc || \"-\"; } };\nconst flag = (cc) => /^[A-Z]{2}$/.test(cc || \"\") ? String.fromCodePoint(...[...cc].map((c) => 0x1f1a5 + c.charCodeAt(0))) : \"\";\nconst METHOD = { tcp: \"TCP\", icmp: \"ICMP\", vpngate: \"自报\", none: \"\" };\n\nfunction renderStatus() {\n  const st = window.__state; if (!st) return;\n  const online = st.nodes.filter((n) => n.online), up = online.filter((n) => n.status === \"up\");\n  $(\"sb-nodes\").textContent = st.nodes.length;\n  $(\"sb-nodes-sub\").textContent = \"在线 \" + online.length + \" · 代理就绪 \" + up.length;\n  const ex = [...new Set((st.policy && st.policy.exclude) || [])].sort();\n  $(\"sb-bl\").textContent = ex.length;\n  $(\"sb-bl-sub\").textContent = ex.length ? ex.map((c) => flag(c) + c).join(\" \") : \"无\";\n  if (!scanData) { $(\"sb-res\").textContent = \"-\"; $(\"sb-cc\").textContent = \"-\"; return; }\n  const exs = new Set(ex);\n  const ok = scanData.items.filter((r) => r.residential && r.latency != null && !exs.has(r.cc));\n  const by = new Map(); for (const r of ok) by.set(r.cc, (by.get(r.cc) || 0) + 1);\n  $(\"sb-res\").textContent = ok.length;\n  $(\"sb-res-sub\").textContent = \"已排除黑名单 · 住宅总数 \" + scanData.residential + \" / 扫描 \" + scanData.total;\n  $(\"sb-cc\").textContent = by.size;\n  const top = [...by.entries()].sort((a, b) => b[1] - a[1]);\n  $(\"sb-cc-sub\").textContent = top.length ? top.slice(0, 8).map(([c, n]) => flag(c) + c + \"·\" + n).join(\" \") + (top.length > 8 ? \" …+\" + (top.length - 8) : \"\") : \"暂无\";\n}\n\n// 给表格单元格补 data-label（窄屏卡片布局用）\nfunction labelize(tbody) {\n  const t = tbody.closest(\"table\"), ths = [...t.querySelectorAll(\"thead th\")].map((x) => x.textContent.trim());\n  for (const tr of tbody.rows) {\n    if (tr.cells.length === 1 && tr.cells[0].colSpan > 1) continue;\n    [...tr.cells].forEach((td, i) => { td.dataset.label = ths[i] || \"\"; });\n  }\n}\n\nfunction render(st) {\n  window.__state = st;\n  $(\"ver\").textContent = st.version ? \"Hub v\" + st.version : \"\";\n  const old = st.nodes.filter((n) => n.online && !n.scan_state);\n  const oa = $(\"old-agent\");\n  oa.hidden = old.length === 0;\n  oa.textContent = old.length\n    ? \"节点 \" + old.map((n) => n.id).join(\"、\") + \" 的 agent 还是旧版，不会扫描。请在该 VPS 上重新执行下方「接入新节点」的命令来更新。\"\n    : \"\";\n  window.__nodes = st.nodes;\n  window.__scanHint = st.nodes.length === 0 ? \"还没有节点接入。\"\n    : old.length === st.nodes.filter((n) => n.online).length && old.length ? \"节点 agent 尚未更新到新版，请重新执行安装命令。\"\n    : st.nodes.some((n) => n.scan_state === \"scanning\") ? \"正在扫描中，通常 1–2 分钟，完成后自动显示。\"\n    : \"agent 已更新但还没有结果：看下方日志是否有「扫描失败 / ip-api 批量查询失败」，或点「立即扫描」。\";\n  $(\"warn\").hidden = st.proxy_auth_set;\n  $(\"install\").textContent = st.install_cmd;\n  $(\"uninstall\").textContent = st.uninstall_cmd || \"\";\n  if (!formReady) {\n    $(\"country\").value = st.policy.country; $(\"port\").value = st.policy.port;\n    $(\"mode\").value = st.policy.mode || \"country\"; $(\"maxc\").value = st.policy.max_conns || 500;\n    $(\"proxy-on\").value = st.policy.proxy_enabled === false ? \"0\" : \"1\";\n    $(\"auto-best\").value = st.policy.auto_best === false ? \"0\" : \"1\";\n    SETS.ex.clear(); (st.policy.exclude || []).forEach((c) => SETS.ex.add(c));\n    SETS.pf.clear(); (st.policy.prefer || []).forEach((c) => SETS.pf.add(c));\n    syncMode(); renderEx(); formReady = true;\n  }\n\n  const body = $(\"nodes\");\n  body.replaceChildren();\n  $(\"nodes-empty\").hidden = st.nodes.length > 0;\n  for (const n of st.nodes) {\n    const tr = document.createElement(\"tr\");\n    const state = !n.online ? \"off\" : n.status === \"up\" ? \"up\" : \"connecting\";\n    const label = !n.online ? \"离线\" : n.status === \"up\" ? \"在线\" : \"连接中\";\n    const s = cell(tr, \"\");\n    const dot = document.createElement(\"span\"); dot.className = \"dot \" + state;\n    s.append(dot, label);\n    nameCell(tr, n.id);\n    cell(tr, n.host && n.port ? n.host + \":\" + n.port : \"-\", \"mono\");\n    cell(tr, n.exit_ip || \"-\", \"mono\");\n    cell(tr, n.country ? flag(n.country) + \" \" + cname(n.country) : \"-\");\n    const isp = cell(tr, (n.isp || \"-\"));\n    if (n.hosting) { const f = document.createElement(\"span\"); f.className = \"flag\"; f.textContent = \"（机房）\"; isp.appendChild(f); }\n    cell(tr, n.latency ? n.latency + \" ms\" : \"-\");\n    cell(tr, ago(st.now - n.last_seen));\n    const ops = document.createElement(\"td\");\n    const rot = document.createElement(\"button\"); rot.className = \"ghost\"; rot.textContent = \"换 IP\";\n    rot.onclick = async () => { rot.disabled = true; try { await api(\"/api/rotate\", { node_id: n.id }); } finally { setTimeout(refresh, 800); } };\n    const del = document.createElement(\"button\"); del.className = \"ghost danger\"; del.textContent = \"移除\"; del.style.marginLeft = \"6px\";\n    del.onclick = async () => { if (confirm(\"从面板移除节点 \" + n.id + \"？（agent 仍会重新上报）\")) { await api(\"/api/nodes/delete\", { node_id: n.id }); refresh(); } };\n    if (n.pin_ip) {\n      const un = document.createElement(\"button\"); un.className = \"ghost\"; un.textContent = \"取消固定 \" + n.pin_ip; un.style.marginLeft = \"6px\";\n      un.onclick = async () => { un.disabled = true; try { await api(\"/api/switch\", { node_id: n.id, ip: \"\" }); } finally { setTimeout(refresh, 800); } };\n      ops.append(rot, un, del);\n    } else ops.append(rot, del);\n    tr.appendChild(ops);\n    body.appendChild(tr);\n  }\n\n  labelize(body);\n  renderProxy(st);\n  renderStatus();\n  // 最新在前（接口已按时间倒序返回），带时间戳；服务端只保留 3 天\n  $(\"logs\").textContent = st.logs\n    .map((l) => new Date(l.ts).toLocaleString(\"zh-CN\", { hour12: false }) + \" [\" + nodeName(l.node_id) + \"] \" + l.line).join(\"\\n\");\n}\n\nconst fmtBytes = (n) => { n = Number(n) || 0; const u = [\"B\", \"KB\", \"MB\", \"GB\", \"TB\"]; let i = 0; while (n >= 1024 && i < 4) { n /= 1024; i++; } return (i ? n.toFixed(1) : n) + \" \" + u[i]; };\nconst fmtSpeed = (bps) => bps ? (bps / 1e6).toFixed(1) + \" Mbps\" : \"-\";\nconst fmtDur = (ms) => { const m = Math.floor(ms / 60000); return m < 60 ? m + \" 分钟\" : m < 1440 ? Math.floor(m / 60) + \" 小时 \" + (m % 60) + \" 分\" : Math.floor(m / 1440) + \" 天 \" + Math.floor((m % 1440) / 60) + \" 小时\"; };\n\nfunction renderProxy(st) {\n  const body = $(\"proxy-body\"); body.replaceChildren();\n  for (const n of st.nodes) {\n    let p = null; try { p = n.proxy_stats ? JSON.parse(n.proxy_stats) : null; } catch {}\n    const tr = document.createElement(\"tr\");\n    nameCell(tr, n.id);\n    if (!p) { const td = cell(tr, \"等待 agent 上报（需更新到新版）\"); td.colSpan = 7; body.appendChild(tr); continue; }\n    const sv = cell(tr, \"\");\n    const dot = document.createElement(\"span\");\n    const live = n.online && p.listening;\n    dot.className = \"dot \" + (!n.online ? \"off\" : live ? \"up\" : \"connecting\");\n    sv.append(dot, !n.online ? \"离线\" : !p.on ? \"已停用\" : p.listening ? \"监听中\" : \"未监听\");\n    cell(tr, p.port || \"-\", \"mono\");\n    cell(tr, p.active + \" / \" + p.max, \"mono\");\n    cell(tr, p.total + \" / \" + p.rejected, \"mono\");\n    cell(tr, fmtBytes(p.up), \"mono\");\n    cell(tr, fmtBytes(p.down), \"mono\");\n    cell(tr, p.since && p.listening ? fmtDur(st.now - p.since) : \"-\");\n    body.appendChild(tr);\n  }\n  labelize(body);\n}\n\nconst SETS = { ex: new Set(), pf: new Set() };\nconst EX_COMMON = [\"JP\",\"KR\",\"US\",\"CA\",\"MX\",\"TH\",\"VN\",\"RU\",\"TW\",\"HK\",\"ID\",\"IN\",\"BR\",\"DE\",\"FR\",\"GB\",\"AU\",\"SG\",\"MY\",\"PH\",\"TR\",\"UA\",\"PL\",\"IT\",\"ES\",\"NL\",\"SE\",\"CH\",\"CN\"];\nconst NORTH_AMERICA = [\"US\",\"CA\",\"MX\",\"GT\",\"BZ\",\"SV\",\"HN\",\"NI\",\"CR\",\"PA\",\"CU\",\"JM\",\"HT\",\"DO\",\"BS\",\"BB\",\"TT\",\"PR\"];\nfunction renderCC(k) {\n  const set = SETS[k], other = SETS[k === \"ex\" ? \"pf\" : \"ex\"];\n  const names = new Map();\n  for (const c of EX_COMMON) names.set(c, \"\");\n  for (const c of (scanData && scanData.countries) || []) if (c.cc) names.set(c.cc, c.country || \"\");\n  for (const c of set) if (!names.has(c)) names.set(c, \"\");\n  const grid = $(k + \"-grid\"); grid.replaceChildren();\n  [...names.keys()].sort().forEach((cc) => {\n    const lb = document.createElement(\"label\"); lb.className = set.has(cc) ? \"on\" : \"\";\n    const cb = document.createElement(\"input\"); cb.type = \"checkbox\"; cb.style.width = \"auto\"; cb.checked = set.has(cc);\n    cb.onchange = () => { if (cb.checked) { set.add(cc); other.delete(cc); } else set.delete(cc); renderEx(); };\n    lb.append(cb, document.createTextNode(flag(cc) + \" \" + cname(cc, names.get(cc))));\n    grid.appendChild(lb);\n  });\n  $(k + \"-sum\").textContent = set.size ? [...set].sort().map((c) => flag(c) + c).join(\" \") : \"无\";\n}\nfunction renderEx() { renderCC(\"ex\"); renderCC(\"pf\"); }\n$(\"ex-clear\").onclick = () => { SETS.ex.clear(); renderEx(); };\n$(\"pf-clear\").onclick = () => { SETS.pf.clear(); renderEx(); };\n$(\"pf-na\").onclick = () => { NORTH_AMERICA.forEach((c) => { SETS.pf.add(c); SETS.ex.delete(c); }); renderEx(); };\nfunction syncMode() { $(\"country-wrap\").hidden = $(\"mode\").value !== \"country\"; }\n$(\"mode\").onchange = syncMode;\n\nasync function loadRoute() {\n  const d = await api(\"/api/route/preview?limit=5\");\n  $(\"route-tag\").textContent = \"模式：\" + ({ country: \"指定国家\", latency: \"延迟优先\", speed: \"速度优先\" }[d.mode] || d.mode) +\n    \" · 国家：\" + (d.country === \"ANY\" ? \"全球\" : d.country) +\n    ((d.prefer || []).length ? \" · 优先 \" + d.prefer.join(\",\") : \"\") +\n    ((d.exclude || []).length ? \" · 排除 \" + d.exclude.join(\",\") : \"\") + \" · 候选 \" + d.total;\n  const body = $(\"route-body\"); body.replaceChildren();\n  $(\"route-empty\").hidden = d.items.length > 0;\n  d.items.forEach((r, i) => {\n    const tr = document.createElement(\"tr\");\n    cell(tr, String(i + 1));\n    cell(tr, r.host + \":\" + r.port, \"mono\");\n    cell(tr, flag(r.cc) + \" \" + cname(r.cc, r.country) + [r.region, r.city].filter(Boolean).map((x) => \" · \" + x).join(\"\"));\n    latCell(tr, r);\n    cell(tr, fmtSpeed(r.speed), \"mono\");\n    cell(tr, String(r.score || \"-\"), \"mono\");\n    nameCell(tr, r.node_id);\n    body.appendChild(tr);\n  });\n  labelize(body);\n}\n\n// ---- 系统诊断\nconst STATUS = { ok: [\"通过\", \"res\"], warn: [\"警告\", \"host\"], fail: [\"失败\", \"bad\"] };\nlet diagData = { nodes: [] }, portChecks = {}, diagTimer = null;\n\nfunction renderDiag() {\n  const box = $(\"diag-out\"); box.replaceChildren();\n  if (!diagData.nodes.length) { const e = document.createElement(\"div\"); e.className = \"empty\"; e.textContent = \"还没有诊断结果，点「运行诊断」。agent 启动约 20 秒后也会自动跑一次。\"; box.appendChild(e); return; }\n  for (const nd of diagData.nodes) {\n    const items = nd.items.slice();\n    const pc = portChecks[nd.node_id];\n    if (pc) items.push({ name: \"代理端口对外可达（Cloudflare 探测）\", status: pc.ok ? \"ok\" : \"fail\",\n      detail: pc.ok ? (pc.host + \":\" + pc.port + \" 可连接\") : ((pc.host ? pc.host + \":\" + pc.port + \" \" : \"\") + (pc.error || \"不可达\") + \"；请检查 VPS 防火墙 / 云安全组是否放行该端口\"), ms: pc.ms ?? null });\n    const cnt = { ok: 0, warn: 0, fail: 0 }; items.forEach((x) => cnt[x.status]++);\n    const h = document.createElement(\"h2\"); h.style.marginTop = \"12px\";\n    h.textContent = nd.node_id + \" · 通过 \" + cnt.ok + \" · 警告 \" + cnt.warn + \" · 失败 \" + cnt.fail + \" · \" + ago(Date.now() - nd.ts);\n    box.appendChild(h);\n    const wrap = document.createElement(\"div\"); wrap.className = \"table-wrap\";\n    const t = document.createElement(\"table\"); \n    const tb = document.createElement(\"tbody\");\n    // 失败排最前\n    const order = { fail: 0, warn: 1, ok: 2 };\n    items.sort((a, b) => order[a.status] - order[b.status]);\n    for (const x of items) {\n      const tr = document.createElement(\"tr\");\n      const st = cell(tr, \"\"); const b = document.createElement(\"span\");\n      b.className = \"badge \" + (STATUS[x.status][1] === \"bad\" ? \"\" : STATUS[x.status][1]);\n      if (x.status === \"fail\") b.style.cssText = \"color:var(--down);border-color:var(--down)\";\n      b.textContent = STATUS[x.status][0]; st.appendChild(b);\n      cell(tr, x.name);\n      const d = cell(tr, x.detail || \"\"); d.style.whiteSpace = \"normal\";\n      cell(tr, x.ms != null ? x.ms + \" ms\" : \"\", \"mono\");\n      tb.appendChild(tr);\n    }\n    t.appendChild(tb); wrap.appendChild(t); box.appendChild(wrap);\n  }\n}\n\nasync function loadDiag() { diagData = await api(\"/api/diag\"); renderDiag(); }\n\n$(\"diag-run\").onclick = async () => {\n  const start = Date.now(), m = $(\"diag-msg\"), btn = $(\"diag-run\");\n  btn.disabled = true; portChecks = {}; m.textContent = \"已下发，节点会在下一次心跳（约 30 秒）内开始诊断…\";\n  try { await api(\"/api/diag/run\", {}); } catch (e) { m.textContent = e.message; btn.disabled = false; return; }\n  clearInterval(diagTimer);\n  let tries = 0;\n  diagTimer = setInterval(async () => {\n    tries++;\n    try {\n      await loadDiag();\n      const st = await api(\"/api/state\");\n      const online = st.nodes.filter((n) => n.online).map((n) => n.id);\n      const done = online.length > 0 && online.every((id) => diagData.nodes.some((d) => d.node_id === id && d.ts >= start));\n      if (done || tries > 30) {\n        clearInterval(diagTimer); btn.disabled = false;\n        for (const id of online) { try { portChecks[id] = await api(\"/api/diag/port?node_id=\" + encodeURIComponent(id)); } catch {} }\n        renderDiag();\n        m.textContent = done ? \"诊断完成\" : \"部分节点未在 90 秒内返回结果（可能离线或 agent 未更新）\";\n      } else m.textContent = \"诊断中…（\" + tries * 3 + \" 秒）\";\n    } catch (e) { m.textContent = e.message; }\n  }, 3000);\n};\n\n$(\"reroute\").onclick = async () => {\n  const m = $(\"reroute-msg\"); m.textContent = \"\";\n  try {\n    const st = await api(\"/api/state\");\n    for (const n of st.nodes.filter((x) => x.online)) await api(\"/api/rotate\", { node_id: n.id });\n    m.textContent = \"已下发，节点会在下一次心跳内按当前路由重新选择\";\n  } catch (e) { m.textContent = e.message; }\n};\n\nlet scanData = null;\n\nfunction latCell(tr, r) {\n  const td = cell(tr, \"\");\n  if (r.latency == null) { td.textContent = \"不可达\"; td.className = \"lat-bad\"; return; }\n  td.className = r.latency < 100 ? \"lat-good\" : r.latency < 250 ? \"lat-mid\" : \"lat-bad\";\n  td.textContent = r.latency + \" ms\";\n  const t = document.createElement(\"span\"); t.className = \"tag\"; t.textContent = METHOD[r.method] || \"\";\n  td.appendChild(t);\n}\n\nfunction scanFiltered() {\n  if (!scanData) return [];\n  const cc = $(\"f-cc\").value, type = $(\"f-type\").value, maxLat = parseInt($(\"f-lat\").value, 10) || 0;\n  const rows = scanData.items.filter((r) =>\n    (!cc || r.cc === cc) &&\n    (type === \"all\" || (type === \"res\" && r.residential) || (type === \"host\" && r.hosting) || (type === \"mob\" && r.mobile)) &&\n    (!maxLat || (r.latency != null && r.latency <= maxLat)));\n  const key = $(\"f-sort\").value;\n  rows.sort(key === \"score\" ? (a, b) => b.score - a.score\n    : key === \"speed\" ? (a, b) => (b.speed || 0) - (a.speed || 0) || (a.latency ?? 1e9) - (b.latency ?? 1e9)\n    : (a, b) => (a.latency ?? 1e9) - (b.latency ?? 1e9) || b.score - a.score);\n  return rows;\n}\n\nfunction renderScan() {\n  renderStatus();\n  if (!scanData) return;\n  $(\"st-res\").textContent = scanData.reachable_residential + \" / \" + scanData.residential;\n  $(\"st-total\").textContent = scanData.total;\n  $(\"st-cc\").textContent = scanData.countries.filter((c) => c.residential > 0).length;\n  $(\"st-time\").textContent = scanData.updated ? ago(Date.now() - scanData.updated) : \"-\";\n\n  const sel = $(\"f-cc\"), cur = sel.value;\n  sel.replaceChildren(new Option(\"全部\", \"\"));\n  for (const c of scanData.countries)\n    sel.appendChild(new Option(flag(c.cc) + \" \" + cname(c.cc, c.country) + \"（住宅 \" + c.residential + \" / \" + c.total + \"）\", c.cc));\n  sel.value = cur;\n\n  const rows = scanFiltered(), body = $(\"scan-body\");\n  body.replaceChildren();\n  $(\"scan-empty\").hidden = scanData.total > 0;\n  $(\"scan-empty\").textContent = window.__scanHint || \"暂无扫描结果。\";\n  for (const r of rows.slice(0, 300)) {\n    const tr = document.createElement(\"tr\");\n    const node = (window.__nodes || []).find((n) => n.id === r.node_id);\n    const ops = document.createElement(\"td\");\n    if (node && (node.pin_ip === r.ip || (node.status === \"up\" && node.exit_ip === r.ip))) {\n      tr.className = \"cur\";\n      const t = document.createElement(\"span\"); t.className = \"badge res\";\n      t.textContent = node.pin_ip === r.ip ? \"已固定\" : \"当前使用\"; ops.appendChild(t);\n    } else if (r.latency != null) {\n      const sw = document.createElement(\"button\"); sw.className = \"ghost\"; sw.textContent = \"切换\";\n      sw.onclick = () => switchTo(r, sw);\n      ops.appendChild(sw);\n    }\n    tr.appendChild(ops);\n    const t = cell(tr, \"\");\n    const b = document.createElement(\"span\");\n    b.className = \"badge \" + (r.hosting ? \"host\" : r.mobile ? \"mob\" : \"res\");\n    b.textContent = r.hosting ? \"机房\" : r.mobile ? \"移动\" : \"住宅\";\n    t.appendChild(b);\n    cell(tr, r.host + \":\" + r.port, \"mono\");\n    cell(tr, flag(r.cc) + \" \" + cname(r.cc, r.country) + [r.region, r.city].filter(Boolean).map((x) => \" · \" + x).join(\"\"));\n    const ut = cell(tr, String(r.sessions || 0), \"mono\");\n    ut.title = \"当前连接数 \" + (r.sessions || 0) + \"，累计用户 \" + (r.users || 0);\n    cell(tr, r.uptime ? fmtDur(r.uptime) : \"-\");\n    cell(tr, (r.proto || \"\").toUpperCase());\n    latCell(tr, r);\n    cell(tr, fmtSpeed(r.speed), \"mono\");\n    cell(tr, r.score ? String(r.score) : \"-\", \"mono\");\n    nameCell(tr, r.node_id);\n    body.appendChild(tr);\n  }\n  labelize(body);\n  if (rows.length > 300) $(\"scan-msg\").textContent = \"仅显示前 300 条，共 \" + rows.length + \" 条符合条件\";\n  else if ($(\"scan-msg\").dataset.busy !== \"1\") $(\"scan-msg\").textContent = \"符合条件 \" + rows.length + \" 条\";\n}\n\nasync function switchTo(r, btn) {\n  const m = $(\"scan-msg\"); m.dataset.busy = \"1\";\n  if (!confirm(\"让节点 \" + r.node_id + \" 切换到 \" + r.host + \"（\" + cname(r.cc, r.country) + \"，\" + r.latency + \" ms）？\\n切换期间代理会短暂中断，约 15–60 秒。\")) return;\n  btn.disabled = true;\n  try {\n    await api(\"/api/switch\", { node_id: r.node_id, ip: r.ip });\n    m.textContent = \"已下发：节点会在下一次心跳（约 30 秒）内开始切换，连不上会自动恢复自动选择\";\n  } catch (e) { m.textContent = \"切换失败：\" + e.message; btn.disabled = false; }\n  setTimeout(() => { m.dataset.busy = \"0\"; refresh(); }, 20000);\n  refresh();\n}\n\nasync function loadScan() { scanData = await api(\"/api/scan?limit=2000\"); renderScan(); if (!$(\"ex-box\").open && !$(\"pf-box\").open) renderEx(); }\n\nasync function loadList() {\n  const r = await fetch(\"/api/proxies?scheme=\" + scheme);\n  if (!r.ok) { $(\"list\").value = \"加载失败：HTTP \" + r.status; return; }\n  const t = await r.text();\n  $(\"list\").value = t || \"\";\n  $(\"list\").placeholder = \"暂无可用代理：没有在线且状态为 up 的节点（隧道可能正在重连，请看下方日志）\";\n}\n\nlet tick = 0, ready = false;\nconst curTab = () => location.hash.slice(1) || \"nodes\";\nasync function loadTab(t) {\n  const p = [];\n  if (t === \"route\") p.push(loadRoute().catch(() => {}));\n  if (t === \"diag\") p.push(loadDiag().catch(() => {}));\n  if (t === \"nodes\" || t === \"install\") p.push(loadList());\n  await Promise.all(p);\n}\n// 30 秒一次：总是拉 /api/state；当前分頁的数据按需拉；扫描+路由（状态栏要用）每 2 分钟一次\nasync function refresh() {\n  if (document.hidden) return;\n  const t = curTab(); tick++;\n  try {\n    render(await api(\"/api/state\"));\n    const p = [loadTab(t)];\n    if (t === \"scan\" || t === \"route\" || !scanData || tick % 4 === 0) {\n      p.push(loadScan().catch((e) => { $(\"scan-msg\").textContent = \"扫描数据加载失败：\" + (e.message || e); }));\n      if (t !== \"route\") p.push(loadRoute().catch(() => {}));\n    }\n    await Promise.all(p);\n  } catch (e) { $(\"save-msg\").textContent = String(e.message || e); }\n}\n\n$(\"save\").onclick = async () => {\n  try {\n    await api(\"/api/policy\", {\n      country: $(\"country\").value.trim(), port: $(\"port\").value.trim(), mode: $(\"mode\").value,\n      max_conns: $(\"maxc\").value.trim(), proxy_enabled: $(\"proxy-on\").value, auto_best: $(\"auto-best\").value, exclude: [...SETS.ex], prefer: [...SETS.pf] });\n    setTimeout(loadRoute, 300); setTimeout(refresh, 400);\n    $(\"save-msg\").textContent = \"已保存，节点会在下一次心跳（约 30 秒）内生效\";\n  } catch (e) { $(\"save-msg\").textContent = e.message; }\n};\n[\"f-cc\", \"f-type\", \"f-sort\"].forEach((id) => $(id).onchange = renderScan);\n$(\"f-lat\").oninput = renderScan;\n$(\"scan-now\").onclick = async () => {\n  const m = $(\"scan-msg\"); m.dataset.busy = \"1\";\n  try { await api(\"/api/scan/now\", {}); m.textContent = \"已下发，节点会在下一次心跳（约 30 秒）内开始扫描，通常 1–2 分钟完成\"; }\n  catch (e) { m.textContent = e.message; }\n  setTimeout(() => { m.dataset.busy = \"0\"; }, 60000);\n};\n$(\"copy-scan\").onclick = () => navigator.clipboard.writeText(\n  scanFiltered().filter((r) => r.latency != null).map((r) => r.host + \":\" + r.port).join(\"\\n\"));\n$(\"fmt-socks\").onclick = () => { scheme = \"socks5\"; loadList(); };\n$(\"fmt-http\").onclick = () => { scheme = \"http\"; loadList(); };\n$(\"copy-list\").onclick = () => navigator.clipboard.writeText($(\"list\").value);\ndocument.querySelectorAll(\"[data-copy]\").forEach((b) => b.onclick = () => navigator.clipboard.writeText($(b.dataset.copy).textContent));\n\nconst BG = { img: \"bg_img\", op: \"bg_op\", ts: \"bg_ts\" };\nconst lsGet = (k) => { try { return localStorage.getItem(k) || \"\"; } catch { return \"\"; } };\nconst lsSet = (k, v) => { try { if (v) localStorage.setItem(k, v); else localStorage.removeItem(k); return true; } catch { return false; } };\nconst bgMsg = (t) => { $(\"bg-msg\").textContent = t; };\n// 本机只是缓存，Cloudflare KV 才是唯一来源\nlet bgImg = lsGet(BG.img), bgOp = parseInt(lsGet(BG.op), 10) || 88, bgTs = parseInt(lsGet(BG.ts), 10) || 0, bgTimer = null;\nfunction applyBg() {\n  document.body.style.backgroundImage = bgImg ? 'url(\"' + bgImg.replace(/\"/g, \"%22\") + '\")' : \"\";\n  document.body.classList.toggle(\"has-bg\", !!bgImg);\n  document.documentElement.style.setProperty(\"--card-a\", bgOp + \"%\");\n  $(\"bg-op\").value = bgOp;\n}\nfunction bgSave() { lsSet(BG.img, bgImg); lsSet(BG.op, String(bgOp)); lsSet(BG.ts, String(bgTs)); }\nasync function bgPush(payload, okText) {\n  try {\n    const j = await api(\"/api/bg\", payload);\n    bgTs = j.ts || bgTs; bgSave();\n    bgMsg(okText || \"已同步到所有设备\");\n  } catch (e) { bgMsg(\"已应用到本机，但云端同步失败：\" + e.message); }\n}\nasync function bgPull() {\n  try {\n    const j = await api(\"/api/bg?since=\" + bgTs);\n    if ((j.ts || 0) > bgTs) {\n      bgImg = j.img || \"\"; bgOp = j.op || 88; bgTs = j.ts; bgSave(); applyBg();\n    } else if (!j.ts && bgImg && bgImg.length < 6e6) {\n      await bgPush({ img: bgImg, op: bgOp }, \"已把本机背景上传到云端，其它设备会自动同步\");\n    }\n  } catch (e) {\n    if (!$(\"bg-msg\").textContent) bgMsg(\"云端同步不可用（\" + e.message + \"），背景仅保存在本机\");\n  }\n}\n$(\"bg-apply\").onclick = () => {\n  const u = $(\"bg-url\").value.trim();\n  if (!/^https:\\/\\/\\S+$/i.test(u)) return bgMsg(\"请填入 https:// 开头的图片链接\");\n  const im = new Image();\n  im.onload = () => { bgImg = u; bgSave(); applyBg(); bgMsg(\"已应用，同步中…\"); bgPush({ img: u }); };\n  im.onerror = () => bgMsg(\"图片无法加载，请检查链接是否可直接访问\");\n  im.src = u;\n};\n$(\"bg-file\").onchange = (e) => {\n  const f = e.target.files[0]; e.target.value = \"\";\n  if (!f) return;\n  if (!/^image\\//.test(f.type)) return bgMsg(\"请选择图片文件\");\n  const fr = new FileReader();\n  fr.onload = () => {\n    const im = new Image();\n    im.onload = () => {\n      const k = Math.min(1, 1920 / Math.max(im.width, im.height));\n      const cv = document.createElement(\"canvas\");\n      cv.width = Math.max(1, Math.round(im.width * k)); cv.height = Math.max(1, Math.round(im.height * k));\n      cv.getContext(\"2d\").drawImage(im, 0, 0, cv.width, cv.height);\n      const data = cv.toDataURL(\"image/jpeg\", 0.82);\n      bgImg = data; bgSave(); applyBg(); bgMsg(\"已应用，同步中…\"); bgPush({ img: data });\n    };\n    im.onerror = () => bgMsg(\"无法读取这张图片\");\n    im.src = fr.result;\n  };\n  fr.readAsDataURL(f);\n};\n$(\"bg-op\").oninput = () => {\n  bgOp = parseInt($(\"bg-op\").value, 10) || 88; bgSave(); applyBg();\n  clearTimeout(bgTimer); bgTimer = setTimeout(() => bgPush({ op: bgOp }), 500);\n};\n$(\"bg-reset\").onclick = () => {\n  bgImg = \"\"; bgOp = 88; bgSave(); applyBg(); $(\"bg-url\").value = \"\";\n  bgPush({ img: \"\", op: 88 }, \"已恢复默认（所有设备）\");\n};\napplyBg();\nbgPull();\nsetInterval(() => { if (!document.hidden) bgPull(); }, 120000);\ndocument.addEventListener(\"visibilitychange\", () => { if (!document.hidden) bgPull(); });\n\nconst TABS = [\"nodes\", \"scan\", \"route\", \"diag\", \"install\", \"logs\"];\nfunction showTab(t) {\n  if (!TABS.includes(t)) t = \"nodes\";\n  document.querySelectorAll(\"section[data-tab]\").forEach((s) => { s.hidden = s.dataset.tab !== t; });\n  document.querySelectorAll(\"#tabs button\").forEach((b) => b.classList.toggle(\"on\", b.dataset.t === t));\n  try { history.replaceState(null, \"\", \"#\" + t); } catch {}\n  window.scrollTo(0, 0);\n  if (ready) { if (t === \"scan\" || t === \"route\") loadScan().catch(() => {}); loadTab(t); }\n}\ndocument.querySelectorAll(\"#tabs button\").forEach((b) => b.onclick = () => showTab(b.dataset.t));\nwindow.addEventListener(\"hashchange\", () => showTab(location.hash.slice(1)));\nshowTab(location.hash.slice(1));\n\nrefresh().then(() => { ready = true; });\nsetInterval(refresh, 30000);\ndocument.addEventListener(\"visibilitychange\", () => { if (!document.hidden) refresh(); });\n</script>\n</body>\n</html>\n";
